programs.luna:
"""A sparse Romance-language cue from familiar articles and word endings."""
READS = ()

ROMANCE_MARKERS = {
    "que", "del", "para", "con", "por", "porque", "como", "tambien",
    "también", "esta", "este", "son", "sobre", "cuando", "está", "las",
    "los", "una", "uno", "desde", "pero", "más", "muy", "se", "nos",
}
ARTICLES = {"a", "o", "os", "as", "da", "do", "das", "dos"}
ENDINGS = {
    "ado", "ada", "ados", "adas", "ano", "ana", "ero", "era",
    "eros", "eras", "ina", "ino", "ivo", "iva", "amos",
}


def step(carry, prefix, upstream):
    """Predict a small positive cue on Romance forms after Romance context appears."""
    document = prefix.document_ids[-1]
    seen = 0 if carry is None or carry[0] != document else carry[1]
    word = prefix.token_strings[-1].strip().lower()
    seen += word in ROMANCE_MARKERS

    if seen >= 3 and (word in ARTICLES or word in ENDINGS):
        value = 0.30
    else:
        value = 0.0
    return (document, seen), value

programs.sol:
"""A negative spelling signal centered on the Latin letter pair fr.

An isolated fr/Fr/FR token is strongest, with case and boundary adjustments.
Longer fr-words respond less; from/front/free are weak exceptions, while
frequency, friction and short franc/fract fragments are stronger. The
mathematical operator frac is weak. Embedded fr and the near-match far
also respond. One previous token detects split f+r and echoes a bare fr
onto its next alphabetic continuation. State resets between documents.
This leaves unrelated, weaker activations unexplained.
"""
READS = ()


def spelling_response(token):
    word = token.lstrip().lstrip('._-/(#').lower()
    if word == 'fr':
        letters = ''.join(c for c in token if c.isalpha())
        if letters.isupper():
            return -4.2
        if letters[0].isupper():
            return -4.6
        if token.startswith('.'):
            return -4.3
        return -4.85 if token[0].isspace() else -5.2
    if token == 'frac':
        return -0.1  # Mathematical fraction notation, not an ordinary word.
    if word.startswith(('from', 'front')):
        return -0.04
    if word.startswith('free'):
        return -0.12 if word in ('free', 'freely') else -0.42
    if word.startswith(('fresh', 'fry', 'fraud')):
        return -0.35
    if word.startswith('fr'):
        if word == 'frequency':
            return -1.6
        if word in ('franc', 'fract') or word.startswith('friction'):
            return -2.0
        if word.endswith(('ly', 'ments')) or word.startswith('francisco'):
            return -0.55
        return -1.1
    if word == 'refr':
        return -2.5
    if word.startswith(('infra', 'infr')):
        return -0.2 if word.startswith('infrastr') else -1.2
    if 'fr' in word:
        return -0.4
    if word == 'far':
        return -0.8
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    value = spelling_response(token)
    same_document = carry is not None and carry[0] == document
    if not same_document and value < -4.0:
        value *= 1.25 if token[0].isspace() else 1.6
    if same_document:
        previous = carry[1]
        continuation = bool(token and token[0].isalpha())
        if continuation and value == 0.0:
            if previous.lower().endswith('fr'):
                value = -0.85
            elif (previous.lower().endswith('f')
                  and token.lower().startswith('r')
                  and not (previous[-1].islower() and token[0].isupper())):
                value = -0.8
    return (document, token), float(value)

"""Reviewing, checking, and consulting are strong lexical signals.

Predict a positive pulse on these word families and their East Asian
counterparts. Review words are strongest; check words are weaker. Also
recognize the short continuation of 'review of/the', inflectional token
fragments, and '顾/顧' compounds. Remember only the previous token, resetting
at document boundaries. Small responses to unrelated words are omitted.
"""

READS = ()

REVIEW_FORMS = {'review', 'reviews', 'reviewed', 'reviewing'}
CHECK_FORMS = {'check', 'checks', 'checked', 'checking', 'checker'}
CONSULT_VERBS = {'consult', 'consulted', 'consulting'}
CONSULT_NOUNS = {
    'consultation', 'consultations', 'consultant', 'consultants', 'consultancy',
}
EXAMINATION = {
    'assess', 'assessed', 'assessment', 'evaluate', 'evaluated', 'evaluation',
    'inspect', 'inspected', 'inspection', 'survey', 'surveyed', 'looking',
}
RECONSIDERATION = {
    'overview', 'recap', 'recall', 'revisit', 'oversight', 'critics', 'glance',
}
EAST_ASIAN = {
    '顾': 6.7, '顧': 5.3,             # attend to, regard
    '不顾': 4.8, '回顾': 3.0,          # disregard, review
    '照顾': 2.45, '照顧': 2.5,         # take care of
    '顾问': 2.2, '顾客': 0.7,          # adviser, customer
    '咨询': 1.0, '諮詢': 1.1,          # consult
    '审': 0.85, '審': 0.7, '审查': 1.2, '审核': 0.9,
    '检查': 0.7, '檢查': 0.7,          # examine, check
    '谈': 0.55, '談': 0.55,            # discuss
    '回忆': 0.9, '复习': 1.2,          # recollect, review
    'レビュー': 1.1, 'チェック': 0.55, # review, check
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip(' \t\r\n._-/(')
    lower = word.lower()
    value = 0.0
    if lower in REVIEW_FORMS:
        value = 2.45 if lower == 'review' else 2.15
        if not raw.startswith(' ') and lower == 'review':
            value = 2.15
        if lower == 'reviewed' and (raw.startswith('-') or word.istitle()):
            value = 0.9
    elif lower in {'reviewer', 'reviewers', 'preview'}:
        value = 1.15
    elif lower in CHECK_FORMS:
        value = 0.85 if lower in {'check', 'checks'} else 0.74
        if not raw.startswith(' '):
            value *= 0.9
    elif lower in CONSULT_VERBS:
        value = 1.5
    elif lower in CONSULT_NOUNS:
        value = 1.05
    elif lower in EXAMINATION:
        value = 0.3
    elif lower in RECONSIDERATION:
        value = 0.45
    value = EAST_ASIAN.get(word, value)

    if previous in REVIEW_FORMS and lower in {'of', 'the'}:
        value = 1.25 if lower == 'of' else 0.45
    elif previous in CHECK_FORMS and lower == 'the':
        value = 0.2
    elif (previous in {'review', 'consult', 'check'}
          and lower in {'ing', 's', 'ed', 'ants'}):
        value = {'review': 1.6, 'consult': 1.4, 'check': 0.6}[previous]
    elif previous in {'顾', '顧'} and word in {'客', '名', '慮', '虑', '自'}:
        value = 1.3
    elif previous == '回顾' and word == '了':
        value = 1.2
    return (doc, lower), float(value)

