"""Estimate the sparse response to words about checking, review, or advice."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].lower()

    if "preview" in token:
        value = 0.8
    elif "review" in token:
        if token.rstrip().endswith("ing"):
            value = 2.1
        elif token.rstrip().endswith("s"):
            value = 2.3
        else:
            value = 2.55
    elif "unchecked" in token:
        value = 0.4
    elif "checking" in token:
        value = 0.6
    elif "checked" in token:
        value = 0.52
    elif "check" in token:
        value = 0.85
    elif "consultation" in token:
