programs.sol:
"""Recognize slash separators and double underscores, rather than ordinary words.

A bare slash is strongest after a word or path segment, weaker after a number
or short variable. Quotes, spaces, or brackets fused with it change its size.
Double underscores and email/package-name @ separators also respond. Slashes
fused to words are weak, with a negative response for common denominator units.
In long mixed-case, digit-rich encoded text, slash loses its usual response;
plus signs and slash-letter combinations instead have negative responses.
"""
import string

READS = ()
BASE64_CHARS = set(string.ascii_letters + string.digits + '+/=')
UNITS = {'cm', 'mm', 'ml', 'kg', 'day', 'hr', 'min', 'sec', 'km'}


def bare_slash(previous):
    if not previous or not previous[-1].isalpha():
        return 1.22
    if not previous.isascii():
        return 1.4
    letters = sum(c.isalpha() for c in previous)
    value = 1.25 if letters == 1 else 1.5 if letters == 2 else 1.95
    if previous.startswith(' ') and letters >= 3:
        value -= 0.16
    if previous.startswith('/'):
        value += 0.15
    elif previous.startswith('.'):
        value += 0.12
    return value


def separator(s, previous):
    if s == '/':
        return bare_slash(previous)
    if s.lstrip() == '/':
        return 0.98
    if s in {'／', '╱', '∕', '⁄'}:
        return 1.28
    if s == '__/':
        return 1.96
    if s == '/__':
        return 0.46
    if s == '__':
        return 0.2 if previous.endswith('_') else 0.8
    if s.lstrip() == '__':
        return 0.4
    if s in {'.__', '__.'}:
        return 0.3
    if s.startswith('/') and s[1:].isalpha():
        word = s[1:]
        if word in UNITS:
            return -0.42
        return 0.16 if len(word) == 1 else -0.1
    if s in {'/(', ')/(', '))/(', '/\\'}:
        return 0.41
    if s.startswith('/') and s[1:] and not s[1:].strip():
        return 0.74 if s.count('\n') == 1 else 0.39
    if (s.endswith('/') and s.count('/') == 1
            and not any(c.isalnum() for c in s)):
        left = s[:-1]
        if '<' in left:  # Closing HTML tags are not path separators.
            return 0.0
        if left == '\\':
            return 1.26
        return 1.0 if left[-1:] in ')]}>={' else 0.67
    if s == '@' and previous and previous[-1].isalnum():
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, run = ('', '') if carry is None or carry[0] != doc else carry[1:]
    encoded = (len(run) >= 24
               and sum(c.isupper() for c in run) > len(run) * 0.15
               and sum(c.islower() for c in run) > len(run) * 0.2
               and sum(c.isdigit() for c in run) > len(run) * 0.08)
    if encoded and s.startswith(('/', '+')):
        value = 0.1 if s == '/' else -1.3
    else:
        value = separator(s, previous)
    for c in s:
        run = (run + c)[-128:] if c in BASE64_CHARS else ''
    return (doc, s, run), float(value)

programs.luna:
"""Predict pulses on common slash and separator tokens."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    # A double underscore before a slash often marks a directory boundary.
    if token.endswith("__/"):
        return None, 2.0
    if token == "/":
        return None, 1.6
    # Slashes can be grouped with a space, bracket, or other left-hand text.
    if token.endswith("/"):
        return None, 0.95
    # Smaller separator cues in repository labels and email-like text.
    if token == "__":
        return None, 0.8
    if "@" in token:
        return None, 0.55
    return None, 0.0

programs.sol:
"""Approximate the strong negative response to English possessive 's.

The previous word distinguishes possession from it's, let's and questions.
Capitalization and length strengthen the default possessive estimate; pronoun
and irregular-plural possessors weaken it. Smaller rules cover other clitics,
bare s, plural apostrophes, and HTML-encoded quotes. Other tokens return zero.
Only a short text tail is retained, resetting between documents.
"""
import re

READS = ()
VERB_CONTRACTIONS = {
    "'m": -1.13,
    "'re": -1.35,
    "'ve": -1.42,
    "'ll": -1.44,
    "'d": -0.9,
}
APOSTROPHES = str.maketrans({'’': "'", '‘': "'"})
IS_SUBJECTS = {'it', 'he', 'she', 'that', 'there'}
QUESTION_WORDS = {'what', 'who', 'where', 'when', 'why', 'how'}
INDEFINITE = {
    'someone', 'anyone', 'everyone', 'noone', 'somebody', 'anybody',
    'everybody', 'nobody', 'something', 'anything', 'everything', 'nothing',
}


def possessive(word):
    lower = word.lower()
    if lower in IS_SUBJECTS:
        return -0.1
    if lower == 'let':
        return 0.25
    if lower == 'here':
        return -0.55
    if lower in QUESTION_WORDS:
        return -1.65 if lower == 'what' else -1.1
    if lower in {'men', 'women', 'people'}:
        return -3.15
    if lower == 'children':
        return -3.9
    if lower == 'one':
        return -2.65
    if lower in INDEFINITE:
        return -3.55
    # A name or an ordinary noun, not an auxiliary contraction.
    return -4.1 - 0.07 * min(len(word), 12) - 0.45 * word[:1].isupper()


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    s = token.translate(APOSTROPHES)
    match = re.search(r'[A-Z]?[a-z]+$|[A-Z]+$', tail)
    word = match.group() if match else ''
    lower = word.lower()
    value = 0.0
    if s.lower() == "'s":
        value = possessive(word)
        if s == "'S" and value < -2:
            value = -4.1
        if token.startswith('‘'):
            value += 1.2
    elif s in VERB_CONTRACTIONS:
        value = VERB_CONTRACTIONS[s]
    elif s == "'t":
        # n + 't is a negative contraction, not a possessive/clitic suffix.
        value = 0.0 if lower.endswith('n') else -1.45
    elif s in {"'n", "'r", "'l"}:
        value = -1.6
    elif len(s) == 2 and s.startswith("'") and s[1].isalpha():
        value = -0.55
    elif s == ';s' and tail.endswith(('&#39', '&#039', '&apos')):
        value = -1.05
    elif s == "'" and lower.endswith('s'):
        value = -0.4
    elif s == 's':
        value = -0.28
        if tail.endswith(("'", '’')):
            before = tail[-2:-1]
            value = -0.75 if before.isspace() or before in '([=' else -2.7
    # Treat escaped newlines as word boundaries too.
    tail = (tail + token).replace('\\n', ' ').replace('\\r', ' ')
    return (doc, tail[-40:]), value

programs.luna:
"""Recognize apostrophe endings: possessive -'s is the strongest cue; common
spoken contractions such as -'ll, -'re, and -'m get a smaller negative value.
Other tokens contribute nothing. This is a coarse lexical approximation."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    token = token.replace("’", "'").replace("‘", "'")
    if token.endswith("'s"):
        value = -4.2
    elif token.endswith(("'ll", "'re", "'m", "'ve", "'d")):
        value = -1.7
    elif token == "'":
        value = -0.5
    else:
        value = 0.0
    return None, value

programs.sol:
"""A compact approximation of the component's main formatting signal.

Written newlines, backslashes, nonbreaking spaces, and markup delimiters
respond more strongly after alphabetic word chunks than after indentation
or code symbols. Each table row is a separator family; its columns describe
the previous token. Escaped quotes, invisible characters, and 'wait' have
separate rules. Ordinary text stays near zero. This deliberately omits
word-specific effects and some rarer punctuation responses.
"""
import unicodedata

READS = ()
FUNCTION_WORDS = set('the a an of to for from at in on by with as is are was '
                     'were be been being and or but if that this these those '
                     'it its his her their my our your than so'.split())

# Previous context: whitespace, symbol, number, letter/identifier, word fragment,
# space-prefixed word. These separator families are not a vocabulary lookup.
BOUNDARIES = {
    'written_newline': (0.09, 0.3, 0.83, 0.38, 0.9, 1.28),
    'backslash': (-0.26, 0.09, 0.34, 0.21, 0.31, 1.64),
    'nonbreaking': (-0.07, 0.69, 0.7, 0.6, 0.88, 1.7),
    'square': (0.01, 0.14, 0.47, 0.49, 0.64, 1.05),
    'dollar': (-0.16, 0.13, 0.13, 0.54, 0.47, 0.89),
    'backtick': (-0.06, 0.06, 0.13, 0.43, 0.38, 0.5),
    'asterisk': (0.03, 0.17, 0.16, 0.12, 0.19, 0.55),
    'angle': (-0.11, 0.1, 0.12, 0.14, 0.27, 0.74),
    'underscore': (-0.08, -0.03, 0.32, 0.39, 0.46, 0.74),
    'pipe': (0.02, 0.31, 0.24, 0.49, 0.74, 0.81),
    'ellipsis': (-0.06, 0.16, 0.31, 0.48, 0.57, 0.75),
    'byte_escape': (0.06, 0.3, 0.51, 0.24, 0.82, 1.17),
}


def context(s):
    q = s.strip()
    if not q or '\n' in s or '\r' in s:
        return 0
    if q.isdigit():
        return 2
    if q.isalpha():
        if len(q) == 1:
            return 3
        return 5 if s.startswith(' ') or q.lower() in FUNCTION_WORDS else 4
    return 3 if q[-1].isalpha() else 1


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    prev = carry[1] if carry is not None and carry[0] == doc else ''
    s = prefix.token_strings[-1]
    q = s.lstrip(' ')
    c = context(prev)
    family = None
    value = 0.003
    if q.lower() == 'wait':
        value = 0.39 if q != 'wait' else 0.32
    elif s == 'n':
        value = -0.025
        if prev.endswith('\\'):
            value = 0.36 if prev.endswith('\\\\') else 0.65
    elif '\x00' in s:
        value = 1.34
    elif any(unicodedata.category(ch) == 'Cf' for ch in s):
        value = 1.2
    elif s.isspace():
        if '\xa0' in s:
            family = 'nonbreaking' if len(q) == 1 else None
            value = -0.10
        elif '\r' in s:
            if '\n' in s:
                value = 0.55 if s.startswith(' ') else 0.06
            else:
                value = 0.05 if '\r' in prev else (0.95 if c >= 3 else 0.35)
        elif '\n' in s:
            value = 0.27 if prev.strip().lower() in FUNCTION_WORDS else -0.025
            if s.count('\n') > 1:
                value *= 0.30
            if s.startswith('  '):
                value += 0.28
        elif len(s) > 1 and '\t' not in s:
            value = (0.40 if c >= 4 else 0.16 if c in (2, 3) else -0.01)
            if prev.endswith(' \n') and len(s) >= 4:
                value = 0.44
        else:
            value = -0.01
    elif q == '\\n':
        family = 'written_newline'
    elif q.startswith('\\x') and len(q) <= 4:
        family = 'byte_escape'
    elif '\\"' in q or "\\'" in q:
        value = 0.70 + 0.20 * s.startswith(' ')
        if q[-1] not in '\"\'':
            value -= 0.42
    elif q == '\\':
        family = 'backslash'
    elif s.startswith(' ') and q.startswith('$') and q.endswith('\\'):
        family = 'dollar'
    elif q.endswith('\\'):
        value = 0.35 if c == 5 else -0.02
    elif q.startswith('\\') and q[-1] in '_$':
        value = 0.60
    elif s.startswith(' ') and q.startswith('\\'):
        value = 0.45
    elif q and set(q) == {'|'}:
        family = 'pipe'
    elif q and set(q) == {'_'}:
        family = 'underscore' if not s.startswith(' ') else None
        if family is None:
            value = 0.5 if c == 5 else 0.0
    elif q and ((set(q) == {'.'} and len(q) >= 3) or set(q) == {'…'}):
        family = 'ellipsis'
    elif s.startswith(' '):
        for symbol, name in (('[', 'square'), ('$', 'dollar'), ('`', 'backtick'),
                             ('*', 'asterisk'), ('<', 'angle')):
            if q.startswith(symbol) and not any(ch.isalnum() for ch in q):
                family = name
                break
    if family:
        value = BOUNDARIES[family][c]
        if family == 'byte_escape' and q.startswith('\\xa'):
            value = 0.1
        if family == 'written_newline' and prev.strip().lower() in FUNCTION_WORDS:
            value = 2.25
        if family == 'pipe' and len(q) > 1:
            value = 0.75 if s.startswith(' ') else 1.05
    return (doc, s), float(value)

