HUMAN = {
    'human': -2.2, 'humans': -1.4, 'humanity': -1.1,
    'female': -1.2, 'females': -1.1, 'male': -1.0, 'males': -0.7,
    'woman': -0.7, 'women': -0.8, 'men': -0.3,
