DESCRIPTORS = {
    'western': -1.7, 'eastern': -1.3, 'southern': -1.4, 'northern': -1.0,
    'modern': -0.7, 'wooden': -0.7, 'foreign': -0.6, 'religious': -0.7,
    'linux': -0.9, 'python': -0.7, 'php': -0.7,
