    '日本人': -3.9, '欧洲': -3.2, '西方': -3.0, '韩国': -2.6,
    '德国': -2.9, '英国': -3.0, '英國': -2.2, '印度': -2.9,
    '法国': -2.5, '美国': -1.5, '美國': -1.3, '台湾': -2.2,
    '台灣': -2.0, '亚洲': -2.0, '中文': -2.3, '英文': -1.2,
    '外国': -2.1, '人类': -1.6, '人類': -1.6, '女性': -1.2,
    '男性': -1.5, '黑': -0.7, '白': -0.4,
