        return carry, CJK[word]
    for name in ('中国', '中國', '日本'):
        if name in word and len(word) <= 6:
            return carry, 0.9 * CJK[name]
    root = word[:-1] if word.endswith('s') else word
    identity = word in IDENTITIES or root in IDENTITIES
