        value = PLACE_STRENGTH.get(word, -1.0)
    elif word in HUMAN:
        value = HUMAN[word] * (0.8 if surface[:1].isupper() else 1.0)
    elif word in COLORS:
        value = -1.0 if word in {'black', 'white'} else -0.65
        if surface[:1].isupper():
            value *= 0.75
    else:
        value = DESCRIPTORS.get(word, 0.0)
        if value == 0.0:
            for stem, strength in COGNATES.items():
                if word.startswith(stem):
                    value = strength
                    break
