"""Partial lexical approximation, with special treatment of document starts.

Document starts use spelling, grammatical word classes, and code-header
forms. Later, the estimate for "and" falls after -ing words and request
verbs, and rises after plural-like -s endings. "Result(s)" distinguishes
references such as "these results" from test/search/programming contexts.
Chat markers and a few stable lexical families have fixed responses.

This is not a full grammar parser: it remembers just the previous token
and document position, resets at document boundaries, and returns zero
for unmodelled text. Most of the component's variance remains unexplained.
"""
READS = ()

ARTICLES = {'a', 'an', 'the'}
PREPOSITIONS = set('of to in on at by for from with about as into over under'.split())
PRESENT_COPULAS = {'am', 'is', 'are', 'be'}
REQUEST_VERBS = set(
    'help explain describe tell give write provide show list suggest create '
    'generate find make use identify compare summarize translate analyze '
    'solve implement fix check collect render update'.split()
)


def start_value(token):
    word = token.strip()
    lower = word.lower()
    if token == '<|im_start|>':
        return -0.310
    if lower == 'and':
        if word.isupper():
            return -0.31
        return -0.795 if token == ' and' else -0.60
    if lower == 'or' or word == '&':
        if word.isupper():
            return -0.15
        return -0.39 if token.startswith(' ') or word == '&' else -0.27
    if word == 'a':
        return 0.09
    if lower in ARTICLES:
        if token.startswith(' ') == word.islower():
            return 0.09
        return -0.12
    if lower in PREPOSITIONS or lower in PRESENT_COPULAS:
        return 0.04
    if lower in {'this', 'these', 'it', 'have', 'which'}:
        return 0.06
    if token == 'package':
        return 0.268
    if token == 'import':
        return 0.165
    if lower in {'using', 'if'}:
        return 0.075
    if word.startswith('#'):
        return 0.18 if word == '#' else 0.088
    if word == '=':
        return 0.15
    if word == '//':
        return -0.142
    if word == '和':
        return -0.44
    if word.startswith('<') and word.endswith('>'):
        return -0.24
    if lower in {'result', 'results'}:
        return -0.43
    if lower in REQUEST_VERBS and word.islower():
        return -0.24
    if word.isascii() and word.isalpha() and len(word) == 1:
        return 0.104 if word.isupper() and not token.startswith(' ') else 0.03
    if word.isdigit():
        return 0.026
    if token.isspace():
        return 0.082 if token == '\n' else 0.021
    if '\ufffd' in token:
        return -0.195
    if any(c.isalpha() and not c.isascii() for c in token):
        return -0.108
    if word.isalpha():
        if word.istitle() and not token.startswith(' '):
            return -0.033
        return -0.12
    return 0.0


# Each set is a familiar word class, with an empirically fitted response.
LEXICAL_GROUPS = (
    ({'moreover', 'furthermore'}, 0.18),              # additive adverbs
    ({'please'}, -0.13),                            # polite request
    ({'sorry'}, -0.05),                             # apology
    ({'although', 'though', 'however', 'since'}, -0.04),  # clause links
    ({'because', 'while', 'whereas'}, 0.032),         # clause links
    ({'could', 'might'}, -0.043),                    # possibility modals
    ({'all'}, -0.05),                               # universal quantifier
    ({'everyone', 'everything'}, -0.08),             # universal pronouns
    ({'already', 'previous', 'last'}, 0.075),         # prior/completed time
    ({'performance'}, 0.10),                        # performance noun
    ({'also'}, -0.035),                             # additive adverb
)
CHAT_MARKERS = {
    '</think>': -0.143,
    '<think>': 0.060,
    '<tool_response>': 0.074,
    '<tool_call>': 0.032,
    '</tool_call>': -0.017,
}


def continuation(token, previous, position):
    word, before = token.strip(), previous.strip().lower()
    lower = word.lower()
    if previous == '<|im_start|>' and word in {'assistant', 'user'}:
        return 0.195 if word == 'assistant' else -0.069
    if word in CHAT_MARKERS:
        return CHAT_MARKERS[word]
    if word in {'and', 'And', 'AND'}:
        if word == 'AND':
            return 0.0
        if word == 'And' or not token.startswith(' '):
            return -0.12 if word == 'And' else -0.060
        value = -0.12 / (position + 1) ** 0.5
        if before.isalpha():
            value -= 0.105 * before.endswith('ing')
            value += 0.034 * (len(before) > 1 and before.endswith('s'))
            value -= 0.18 * (before in REQUEST_VERBS)
            value -= 0.09 * (before in PREPOSITIONS)
            value -= 0.04 * before.endswith(('ion', 'ment'))
        value -= 0.084 * previous.isspace()
        value -= 0.067 * (';' in before)
        return value
    if token in {'/or', '-and'}:
        return -0.22 if token == '/or' else -0.19
    if lower == 'or':
        if word != 'or' or not token.startswith(' '):
            return 0.0
        value = -0.12 / (position + 1)
        if before.isascii() and before.isalpha():
            value += 0.03
            value -= 0.03 * (len(before) <= 3)
            value += 0.03 * (len(before) > 1 and before.endswith('s'))
            value -= 0.05 * (before in PREPOSITIONS)
        elif before.endswith(','):
            value += 0.03
        elif before and not before.isalnum():
            value -= 0.034
        elif before.isdigit():
            value -= 0.020
        return value
    if word == '&':
        return 0.044
    if token.startswith(' ') and lower in {'able', 'unable'}:
        return -0.10
    if word in {'.py', '.git', '.rs', '.java', '.go'}:
        return 0.115 if word in {'.py', '.git'} else -0.075
    if token.startswith(' ') and lower in {'result', 'results'}:
        if before in {'a', 'this', 'these', 'same', 'different', 'which'}:
            return 0.10
        if before in {'test', 'search', 'research', 'assert', 'return', 'edit'}:
            return -0.33
        return -0.03 if lower == 'result' else -0.07
    if lower == 'well':
        return -0.069 if token == ' well' else -0.02
    # Small spelling families, not token-ID lookups.
    if lower.startswith('benefit'):
        return -0.12
    family = lower.strip('_./()').rstrip('s')
    if family in {'resource', 'module'}:
        return -0.10 if family == 'resource' else 0.07
    # Chinese result and conjunction forms.
    if word == '结果':
        return -0.30 if previous.strip() not in {'，', '。', '！'} else -0.10
    if word == '和':
        return 0.062
    if word in {'并', '及', '，并'}:
        return -0.245 if word == '并' else -0.15
    if word in {'且', '而且'}:
        return 0.18 if previous.strip() == '，并' else 0.33
    for words, value in LEXICAL_GROUPS:
        if lower in words:
            return value
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ''
    else:
        _, position, previous = carry
    value = (start_value(token) if position == 0
             else continuation(token, previous, position))
    return (doc, position + 1, token), float(value)

