"""A mostly negative lexical response to curtains, coverings and displays.

Curtain characters and English curtain words are strongest; banners, barriers,
soft furnishings, advertising and panoramic views are weaker. These are token
cues, not a claim that every mention of these topics activates the component.
A few independent Japanese/Chinese lexical cues and message-boundary signals
are included. Split Unicode characters are recognized when they become legible.
"""
READS = ()

HANGINGS = {'挂', '掛', '掛け', '旗', '旗帜', '巾', '地毯'}
COVER_CHARACTERS = {'屏', '障', '膜', '屏障', '薄膜', '伞', '傘', '毯', '幌'}
COVER_WORDS = {'一幅', '大幅', '幅度', '挂牌', '悬挂', '挂在',
               '红旗', '国旗', '毛巾', '全景', '壁画', '壁纸', '海报'}
CURTAIN_COMPOUNDS = {'开幕', '開幕', '闭幕', '閉幕', '幕后', '幕後', '窗帘'}
BANNERS_AND_LIGHTS = {'banner', 'banners', 'lantern', 'lanterns'}
