               'blanket', 'blankets', 'shutter', 'shutters', 'veil',
               'tape', 'plush', 'canopy', 'stripe', 'stripes', 'roof'}
ADVERTISING = {'advertisement', 'advertisements', 'advertise', 'advertised',
               'advertising', 'advertiser', 'advertisers', 'poster',
               'posters', 'billboard', 'billboards', 'slogan', 'slogans'}
DISPLAY_SURFACES = {'canvas', 'canvases', 'tent', 'tents', 'membrane',
                    'membranes', 'wallpaper', 'portrait', 'portraits', 'mural'}
LAYOUT = {'fullscreen', 'rowspan', '.documentelement', '.scrollto'}


def lexical_value(raw):
    token = raw.strip()
    word = token.lower()
    if token == '幕':
        return -3.4
    if token in {'帘', '簾', '一幕'}:
        return -2.0 if token != '簾' else -1.0
    if token == '帷':
        return -1.6
    if token in CURTAIN_COMPOUNDS:
        return -1.25
    if token in {'幅', '막', '招牌', '标语', '標語'}:
        return -1.1
    if token in HANGINGS:
        return -0.78
    if token in COVER_CHARACTERS or token in COVER_WORDS:
        return -0.5
    if token in {'帆', '幡', '屏幕', '显示屏'}:
        return -0.25
    if token in {'落幕', '序幕'}:
        return -0.8
    if token in {'广告', '廣告'}:
        return -0.55
    # Narrow lexical responses outside the covering vocabulary.
    if token in {'僕', '懐', '縁', '副', '극', '폭'}:
        return -0.5
    if word == 'реклам':
        return -0.92
    if token == 'Advertisement' and not raw.startswith(' '):
        return -1.1
    if token == 'cloth':
        return -0.65 if not raw.startswith(' ') else -0.06

    value = None
    if word in {'curtain', 'curtains', 'drapery', 'draperies'}:
        value = -1.8
    elif word in BANNERS_AND_LIGHTS:
        value = -0.85
    elif word in COVERINGS or word == 'pornography':
        value = -0.65
    elif word == 'panoramic':
        value = -0.9
    elif word in {'panor', 'panorama'}:
        value = -0.45
    elif word in {'barrier', 'barriers'}:
        value = -0.48
    elif word in FURNISHINGS or word in ADVERTISING:
        value = -0.3
    elif word in DISPLAY_SURFACES or word in {'flag', 'flags', 'blinds',
                                            'porn', 'porno', 'pornhub', 'экран'}:
        value = -0.23
    elif word in {'fabric', 'fabrics', 'textile', 'textiles', 'wall', 'walls'}:
        value = -0.12
    elif word in {'screen', 'screens'}:
        value = -0.08
    elif word in LAYOUT:
        value = -0.5
    elif word in {'clothes', 'clothing'}:
        value = 0.13
    if value is not None:
        # Proper names and identifier fragments generally respond less strongly.
        if token.istitle():
            value *= 0.75
        if not raw.startswith(' ') and token.isascii() and word not in LAYOUT:
            value *= 0.65
        return value
    if token == '</tool_response>':
        return 0.21
    if token == '<think>':
        return 0.13
    if token == '<tool_response>':
        return -0.055
    return 0.0015


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    if raw == '\ufffd':
        completed = prefix.text_prefixes[-1][-1:]
        if completed != '\ufffd':
            raw = completed
    return None, float(lexical_value(raw))

