"""A lexical approximation to an 'agent' detector, not general semantic agency.

The strongest response names an agent, including code-style spellings and
attached 'reagent'. Agencies, a small set of acting roles, and chemical agents
have weaker responses. 'Of' and 'for' immediately after these words retain some
response. A shared UTF-8 fragment of CJK cutting characters and a few conversation
delimiters have separate responses.
Unlisted words receive zero; fine token-specific effects are deliberately omitted.
"""
READS = ()
ACTING_ROLES = {'actor', 'actors', 'assistant', 'assistants', 'broker',
                'brokerage', 'crew', 'army', 'soldier', 'soldiers'}
CHEMICAL_AGENTS = {'detergent', 'antigen', 'antibiotic', 'aeros'}
# UTF-8 E5 89: shared prefix of 剂, 剤, 剥 and other cutting characters.
# This token is an incomplete character and decodes alone as replacement text.
CUTTING_CHARACTER_PREFIX = 20741
DIALOGUE_MARKERS = {
    '<tool_call>': 0.24,
    '</tool_call>': -0.09,
    '<tool_response>': -0.12,
    '<think>': 0.13,
    '</think>': -0.27,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous, strength = ('', 0.0)
    if carry is not None and carry[0] == doc:
        _, previous, strength = carry
    token = prefix.token_strings[-1]
    spelling = token.strip().lstrip('-_/.(')
    word = spelling.lower()
    spaced = token.startswith(' ')
    title = bool(spelling) and spelling[0].isupper()
    value = DIALOGUE_MARKERS.get(token, 0.0)
    if word in ('agent', 'agents'):
        value = 5.0 if title else 4.7
        if spaced:
            value = 5.2 if title else (5.55 if word == 'agent' else 4.6)
        elif token.startswith('-'):
            value = 5.8 if title else 5.0
        elif token.startswith('('):
            value = 3.0
        if not spaced and previous.strip().lower() == 're':
            value = 3.0
        elif spaced and previous.strip().lower() in ('free', 'special', 'user'):
            value += 1.0
        elif spaced and previous.strip().lower() == 'contrast':
            value -= 1.4
    elif word in ('agency', 'agencies'):
        value = 1.0 if title or word == 'agencies' else 0.85
    elif word.startswith('agen'):
        value = 0.4
    elif spaced and word in ACTING_ROLES:
        value = 0.45
    elif spaced and word == 'brokers':
        value = 0.9
    elif spaced and word in CHEMICAL_AGENTS:
        value = 0.7
    elif spaced and word == 'drug':
        value = 0.5
    elif spaced and word in ('drugs', 'antibody', 'dose', 'ingredients'):
        value = 0.35
    elif spaced and word in ('adult', 'adults'):
        value = 0.8 if word == 'adult' else 0.35
    elif spaced and word in ('customer', 'customers'):
        value = -0.5 if word == 'customer' else -0.35
    elif word in ('client', 'clients'):
        value = 0.25
    elif token in ('剂', '劑', '剤'):
        value = 4.0
    elif token in ('代理', '代理商', '代理人'):
        value = 1.4 if token == '代理' else 1.9
    elif token == '成人':
        value = 0.8
    elif token in ('局', '先锋'):
        value = 1.2
    elif prefix.token_ids[-1] == CUTTING_CHARACTER_PREFIX:
        value = 2.85
    elif token == '兵':
        value = 0.6
    elif token in ('药', '藥'):
        value = 0.35
    if word == 'of':
        value = 0.5 * max(strength, 0.0)
        if previous.strip().lower() in ('dose', 'army', 'crew', 'staff'):
            value = 0.65
    elif word == 'for':
        value = 0.1 * max(strength, 0.0)
    return (doc, token, value), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:4493 -- an "agent" detector.

This component fires on the English word "agent" (and "agents", "Agent", "-agent",
"AGENT"), which is its main job: about 5 on those tokens and near 0 elsewhere.
It also fires, more weakly, on the "of" right after an agent-type noun ("an agent of
the State", "the causative agents of ...", about 1.2), on "agency"/"agencies" (about 1),
and on the Chinese/Japanese words for agent or chemical agent (剂, 劑: about 4.5; 代理:
about 1.3). Everything else is 0.

Why: it is a token-identity feature for the concept "agent". Predicting 5 for the word and
about 1 for the related forms captures most of the variance, since the activation is
close to zero on almost all tokens and large only on these few.
"""

AGENT_FORMS = {"agent", "agents", "-agent", "-agents"}
AGENCY_FORMS = {"agency", "agencies"}
AGENT_NOUNS = AGENT_FORMS | AGENCY_FORMS
CHEMICAL_AGENT_CHARS = {"剂", "劑"}

READS = ()


def word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    """Activation at the newest token, from that token and the one before it in the same document."""
    token = word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    previous = word(prefix.token_strings[-2]) if same_doc else ""
    if token in AGENT_FORMS or (token.endswith("agent") and token != "agento"):
        return None, 5.0
    if token == "of" and previous in AGENT_NOUNS:
        return None, 1.2
    if token in AGENCY_FORMS:
        return None, 1.0
    if token.strip() in CHEMICAL_AGENT_CHARS:
        return None, 4.5
    if token == "代理":
        return None, 1.3
    return None, 0.0

