WORD_CLASSES = (
    (frozenset('anything everything nothing either neither'.split()), -0.09),
    (frozenset('quite pretty simply truly almost rather'.split()), -0.08),
    (frozenset('several various'.split()), -0.07),
    (frozenset('real true genuine exact perfect absolute'.split()), -0.06),
    (frozenset('who whom whose what which how when'.split()), -0.014),
    (frozenset('they their theirs themselves'.split()), -0.02),
    (frozenset('first last'.split()), -0.03),
    (frozenset('shown known located listed described used'.split()), 0.025),
)

MARKERS = {
    '<think>': 0.12,
    '</think>': -0.02,
    '</tool_response>': 0.115,
    '</tool_call>': -0.05,
    '<|im_start|>': 0.02,
    '<|im_end|>': 0.0,
    '<|endoftext|>': -0.008,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    word = token.strip().lower()
    prev_word = previous.strip().lower()
    value = 0.001

    for words, offset in WORD_CLASSES:
        if word in words:
            value += offset

    if word in ('be', 'have', 'not', 'also'):
        if prev_word in ('must', 'should'):
            value -= 0.06
        elif prev_word in ('may', 'shall'):
            value += 0.06
        elif prev_word in ('can', 'could', 'will'):
            value += 0.02
    if word == 'be' and prev_word == 'to':
        value -= 0.02
    if word in ('am', 'is', 'are', 'was', 'were', 'have', 'has', 'had'):
        if prev_word in ('you', 'he', 'she', 'they'):
            value -= 0.03
    if word in ("'t", '’t') and prev_word in ('don', 'doesn', 'didn'):
        value += 0.05
    if word == 'al' and prev_word == 'et':
        value += 0.12
    if ',' in token and prev_word == 'alternatively':
        value += 0.05

    if token in MARKERS:
        value = MARKERS[token]
        if token == '<|im_start|>' and start:
            value = 0.08
        elif token == '<|im_end|>':
            if previous.strip().endswith('.'):
                value = 0.07
            elif previous == '</tool_response>':
                value = -0.06
            elif previous == '</tool_call>':
                value = -0.035

    return (doc, token), float(value)

