CONJ = {" and", " or", " nor", "和", "与", "或", "及", " и", " &", "、", "/or"}
CLAUSE = {" there", " you", " then", " to", " if", " although", " yet", " also", " that",
          " it", " they", " I", " we", " he", " she", " this", " so", " because", " when",
          " which", " who", " while", " there", " is", " are", " be", " was", " were"}
