LOW_CONTENT_WORDS = {
    "a", "an", "the", "and", "or", "but", "if", "to", "of", "for",
    "in", "on", "at", "by", "with", "from", "as", "than", "that",
    "this", "it", "he", "she", "they", "we", "i", "you", "there",
    "is", "are", "was", "were", "be", "been", "do", "does", "did",
    "one", "two", "zero", "not", "no", "so", "then", "which", "who",
}


def after_coordination(prefix):
    t = prefix.position
    if t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return False
    previous = prefix.token_strings[-2]
    connector = previous.strip().lower()
    if connector not in COORDINATORS:
        return False
    if connector in UNSPACED_COORDINATORS:
        return True
    if previous[:1].isspace():
        return True
    if t < 2:
        return False
    if prefix.document_ids[-3] != prefix.document_ids[-1]:
        return True
    before = prefix.text_prefixes[-3]
    return not before or not (before[-1].isalnum() or before[-1] == "_")


def step(carry, prefix, upstream):
    if not after_coordination(prefix):
        return carry, 0.0
    word = prefix.token_strings[-1].strip().lower()
    if word in LOW_CONTENT_WORDS:
        return carry, -0.55
    if any(ch.isalpha() for ch in word):
        return carry, 0.65
    return carry, -0.4

