"""Negative spelling response to en-/em-, strongest for short fragments.

En and separator-attached en (as in locale codes) are especially strong.
Word-initial fragments are stronger than suffix fragments. Longer words are
handled by broad spelling families, not a vocabulary lookup. The weak end,
English, enough, ensure, entire, email and emotion families are exceptions.
A small group of environment/engineering/enemy translations and en
transliterations is included. Unrecognized tokens return zero.
"""
import re

READS = ()
WORD = re.compile(r'[A-Za-z]+')


def response(token, previous):
    if token.startswith('<|'):
        return 0.0
    if token.startswith(('环境', '環境', '환경')):
        return -1.25
    if token.startswith(('敵', '敌')):
        return -1.95
    if token in ('工程', '工程师', '引擎'):
        return -0.65
    if token in ('エン', '엔', '恩', 'эн'):
        return -1.4
    match = WORD.search(token)
    if not match or any(c.isalpha() for c in token[:match.start()]):
        return 0.0
    word = match.group()
    low = word.lower()
    head = token[:match.start()]
    initial = bool(head) or not previous[-1:].isalpha()
    if low == 'en':
        if word == 'En':
            return -3.9
        if any(c in head for c in '/_-') or previous.endswith(('://', '/')):
            return -3.95
        if any(c in head for c in "'’"):
            return -2.0
        return -2.72 if initial else -0.4
    if low == 'em':
        if token.startswith(' '):
            return -1.8
        return -1.25 if initial or word[0].isupper() else -0.23
    if 'empty' in low:
        return -0.85
    if 'involv' in low:
        return -0.88
    if low.startswith(('especial', 'essential')):
        return -0.65
    if not low.startswith(('en', 'em')):
        return 0.0
    if low.startswith(('end', 'english', 'enough', 'ensur', 'entire')):
        return -0.07
    if low.startswith(('email', 'emotion', 'emission', 'emerg')):
        return -0.22
    if low.startswith('env'):
        return -1.9 if len(low) == 3 else -1.2
    if low == 'emb':
        return -2.85 if initial or word[0].isupper() else -1.45
    if low.startswith(('enab', 'enem', 'enrol', 'envel', 'enz')):
        return -1.95
    if low.startswith('employee'):
        return -0.6
    if low.startswith(('ement', 'emat')):
        return 0.0
    if low.startswith(('emb', 'employ')):
        return -1.4 if initial or word[0].isupper() else -0.65
    if len(low) <= 3:
        return -1.3 if initial else -0.08
    return -0.72 if initial or word[0].isupper() else -0.06


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, token), response(token, previous)

