import math
import unicodedata

READS = ()
D_LETTERS = ('d', 'D', 'д', 'Д', 'د', 'ด')
STRONG_ENDINGS = {'er', 'ers', 'es', 'en', 'el'}
OTHER_ENDINGS = {
    'em', 'et', 'an', 'on', 'as', 'os', 'ic', 'ing', 'ings',
    'ation', 'ations', 'al', 'or', 'ar', 'is', 'at', 'am',
    'ia', 'ie', 'ness',
    'ов', 'ом', 'ат', 'ел', 'ер', 'атель', 'ет', 'ем',
    'ев', 'ой', 'ор', 'ель', 'еш',
}
LOW_ENDINGS = {'ed', 'ly', 'le', 'ent', 'ish'}
ARABIC_ENDINGS = set('ةهىيیاو')


def response(s, previous):
    # Baseline plus an extra response for short preceding spelling pieces.
    lower = s.lower()
    if s in {"'", '’'}:
        base, extra = -0.07, 1.01
    elif not s or s[0].isspace():
        return 0.0
    elif s.isdigit():
        base, extra = -0.05, -0.18
    elif s in {'-', '‐', '‑'}:
        base, extra = 0.0, 0.38
    elif len(s) == 1 and (
        s.isalpha() or unicodedata.category(s).startswith('M')
    ):
        if lower in 'aeioаеоиыі':
            base, extra = 0.48, 0.94
        elif lower in 'uyуь':
            base, extra = 0.12, 0.80
        elif s in ARABIC_ENDINGS or (
            '\u0e00' <= s <= '\u0e7f'
            and unicodedata.category(s).startswith('M')
        ):
            base, extra = 0.52, 0.71
        elif unicodedata.normalize('NFD', lower)[0] in 'aeiou' or s == 'ə':
            base, extra = 0.16, 0.51
        else:
            base, extra = 0.22, 0.17
    elif lower in STRONG_ENDINGS:
        base, extra = 0.39, 1.46
    elif lower in OTHER_ENDINGS or s.startswith('ерж'):
        # ерж continues the Russian stem держ- (hold).
        base, extra = 0.05, 0.69
    elif lower in LOW_ENDINGS:
        base, extra = -0.06, 0.17
    elif s.isalpha():
        if lower.startswith('e') and len(s) <= 3:
            base, extra = 0.23, 0.02
        elif lower[0] in 'iu':
            base, extra = -0.03, -0.38
        else:
            base, extra = -0.05, -0.12
    else:
        return 0.0
    strength = math.exp(-(len(previous.strip()) - 1) / 3)
    return base + extra * strength


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    value = response(s, previous) if previous.endswith(D_LETTERS) else 0.0
    if not previous and s.strip() in D_LETTERS:
        value = 0.65
    if s == '\x00' and previous.endswith(D_LETTERS):
        # NUL bytes separating letters in UTF-16-like text do not break spelling.
        return (doc, previous), 0.35
    return (doc, s), value

