        value = -0.5
    elif token in {"で", "를", ";s"}:
        value = -0.4
    else:
        value = 0.0
    return None, value

programs.sol:
"""A lexical quantity detector with grammatical exceptions.

Written small cardinals and added/alternative amounts are positive. Definite
numbers and distributive or negative uses are weaker or negative; reciprocal
'each other' and 'one another' are strongly negative. 'One of' remains active
on 'of'. A small multilingual quantity vocabulary is also recognized.
Matching is lexical, including punctuation-delimited identifier pieces.
The state holds at most six tokens and resets at clause/document boundaries.
Other tokens are zero; weak background lexical responses are not modeled.
"""
READS = ()
CARDINALS = dict(zip('one two three four five six seven eight nine ten'.split(),
                    (1.55, 1.32, 1.36, 1.36, 1.26, 1.28, 1.25, 1.07, 1.12, .86)))
TEENS = set('eleven twelve thirteen fourteen fifteen sixteen seventeen '
            'eighteen nineteen'.split())
TENS = set('twenty thirty forty fifty sixty seventy eighty ninety'.split())
DEFINITE = set('the this these those other'.split())
ORDINAL_OR_REPLACEMENT = set(
    'first second third fourth fifth sixth seventh eighth ninth tenth '
    'last next previous subsequent some another new'.split()
)
POSSESSIVE = set('my your his her its our their whose'.split())
QUANTITIES = {'several': 1.48, 'multiple': 1.04, 'few': .32, 'numerous': .57,
              'different': .56, 'various': .56, 'additional': .3}
TRANSLATED = {
    'một': 1.45, 'один': 1.3, 'одна': 1.3, 'одно': 1.3,
    'два': 1.55, 'две': .9, 'три': .95, 'zwei': 1.0,
    'deux': .7, 'trois': .75, 'nhiều': 1.0, 'các': 1.5, 'những': 1.7,
    'plusieurs': 1.25, 'несколько': 1.25, 'mehr': 1.0, 'mais': .53,
    'más': .48, 'более': .56, '여러': 1.4,
}


def number_value(w, prev):
    value = CARDINALS.get(w, .75 if w in TEENS else .5 if w in TENS else .33)
    if prev in ORDINAL_OR_REPLACEMENT:
        return -.92 if w == 'one' else -.4 if w == 'two' else -.2
    if prev in DEFINITE:
        return {'one': -.48, 'two': -.68, 'three': -.28, 'four': -.02}.get(w, .12)
    if prev in POSSESSIVE:
        return -.1 if w == 'one' else -.4 if w == 'two' else .1
    if prev in {'any', 'no', 'each', 'every', 'all'}:
        return ({'any': -1.75, 'no': -2.22, 'each': -2.15,
                 'every': -1.65, 'all': -.2}[prev] if w == 'one' else -.9)
    if prev in {'a', 'an', 'which', 'number', 'same', 'not', "n't"}:
        return value - (1.1 if w == 'one' else .85)
    if prev in {'in', 'into', 'from', 'with', 'to', ',', 'and'}:
        return value + .18
    if prev in {'only', 'just'}:
        return value + .35
    return value - (.22 if prev in {'of', 'that', 'if', 'when', 'or'} else 0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = carry[1] if carry is not None and carry[0] == doc else ()
    prev_raw = recent[-1] if recent else ''
    prev = prev_raw.strip().lower()
    raw = prefix.token_strings[-1]
    word = raw.strip().strip('_-.\'"“”‘’')
    w = word.lower()
    value = TRANSLATED.get(w, 0.0)
    if w in CARDINALS or w in TEENS or w in TENS or w == 'hundred':
        value = number_value(w, prev) + (.25 if word[:1].isupper() else 0)
        if raw == word and word[:1].islower() and prev_raw[-1:].isalpha():
            value = .25  # a number fragment inside a larger word
    elif w in QUANTITIES:
        value = QUANTITIES[w]
        if prev in DEFINITE or prev in ORDINAL_OR_REPLACEMENT:
            value = -.2
        elif w in {'different', 'various', 'additional'}:
            if prev in {'a', 'many'}:
                value = 0.0
            elif prev in {'any', 'each', 'every', 'no'}:
                value = -.65
    elif w == 'more':
        value = 1.25
        if prev in {'no', 'any'}:
            value = -1.75
        elif prev in {'the', 'nothing', 'some', 'once', 'ever', 'not'}:
            value = 0.0
        elif prev in POSSESSIVE or prev in {
            'a', 'much', 'little', 'few', 'bit', 'lot', 'many', 'anything'
        }:
            value = .5
        elif prev in {'in', 'to', 'with', ',', 'but', 'one'}:
            value = 1.55
        elif prev in {'even', 'out', 'other'}:
            value = .85
    elif w == 'another':
        value = -4.23 if prev == 'one' else 1.02 if word[:1].isupper() else .82
        if prev != 'one' and any(s.strip().lower() == 'one' for s in recent):
            value = -1.25
    elif w == 'other':
        if prev == 'each':
            value = -3.76
        elif prev in {'any', 'every', 'all', 'no'}:
            value = -1.12
        elif prev == 'the' or prev in CARDINALS or prev in QUANTITIES:
            value = -.42
    elif w in {'longer', 'fewer'} and prev in {'no', 'any'}:
        value = -1.64 if w == 'longer' else -1.35
    elif w == 'of' and prev in {'one', 'two'}:
        value = .55
        if prev == 'one':
            value = 2.3 if prev_raw.strip()[:1].isupper() else 1.4
            before = recent[-2].strip().lower() if len(recent) > 1 else ''
            if before in {'any', 'no'}:
                value = 0.0
            elif before in {'each', 'every', 'the', 'which', 'not'}:
                value = .7
    elif prev == 'one' and w in {
        'such', 'thing', 'way', 'specific', 'particular', 'possible',
        'important', 'essential', 'last', 'final'
    }:
        value = 2.65 if w == 'such' else 1.0 if w in {'last', 'final'} else 1.4
        if w in {'such', 'way'} and prev_raw.strip()[:1].isupper():
            value += .55
    elif prev == 'một' and w == 'số':
        value = 2.0
    if prev == 'each' and w in {'side', 'part', 'end', 'case', 'step', 'time'}:
        value = -1.15 if w == 'side' else -.75 if w in {'part', 'end'} else -.3
    recent = () if any(c in raw for c in '.!?;\n') else (recent + (raw,))[-6:]
    return (doc, recent), float(value)

programs.haiku:
"""Quantity words: spelled-out counts ("one", "two", ... "nine") and words like
"several", "more" or "another" make this component fire positive. A negator or
distributive word just before them flips the sign: "no one", "no more",
"each other", "every other", "any other" are all strongly negative. Digits,
"many", "some", "both" and "each" on their own stay near zero.

Rule, per token (the previous token is read from the prefix):
  - count or quantity word: about +1.2 ("several" +1.4, "ten" only +0.3);
    foreign equivalents of "some / several" (một, hai, những, các, plusieurs,
    два, один, zwei, jed, trois, mehr): about +1.0
  - after no / each / any / every / all: -2.0 (so "no one", "each other")
  - after the / these / those: -0.5 ("the two", "the other")
  - "another" after "one": -4.0 ("one another")
  - "of" after "one": +1.5 ("one of")
Everything else predicts 0.
"""

READS = ()

COUNTS = {
    "one": 1.3, "two": 1.15, "three": 1.15, "four": 1.2, "five": 1.2, "six": 1.2,
    "seven": 1.15, "eight": 1.0, "nine": 0.9, "ten": 0.3,
}
QUANTITY = {
    "several": 1.4, "more": 1.2, "multiple": 1.0, "another": 0.7, "various": 0.6,
    "numerous": 0.5, "different": 0.4, "few": 0.3,
}
FOREIGN = {"một", "hai", "những", "các", "plusieurs", "два", "один", "три", "zwei",
           "jed", "trois", "mehr"}
NEGATORS = {"no", "each", "any", "every", "all"}
DETERMINERS = {"the", "these", "those"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    cur = _word(prefix.token_strings[-1])
    prev = _word(prefix.token_strings[-2]) if len(prefix) > 1 else ""
    if cur == "of" and prev == "one":
        return carry, 1.5
    if cur == "another" and prev == "one":
        return carry, -4.0
    if cur == "other":
        base = 0.0
    elif cur in COUNTS:
        base = COUNTS[cur]
    elif cur in QUANTITY:
        base = QUANTITY[cur]
    elif cur in FOREIGN:
        base = 1.0
    else:
        return carry, 0.0
    if prev in NEGATORS and (cur == "other" or base > 0):
        return carry, -2.0
    if prev in DETERMINERS and base > 0:
        return carry, -0.5
    if cur == "other" and prev in DETERMINERS:
        return carry, -0.4
    return carry, base

programs.sol:
"""A signal for line-opening formatting and source-code declarations.

After a newline, respond to indentation, bullets, headings, comments and
bare declaration words. Three-space indentation tokens are strongest;
wider four-column indentation levels gradually weaken. Code words and
hashes used mid-line often have the opposite sign. Ordinary text is zero.
Responses near the start of a document are somewhat stronger. URL
separators and tab-plus-newline tokens have small additional responses.
"""
READS = ()

# (line-opening response, mid-line response) for source-code words.
CODE_WORDS = {
    'import': (2.45, -0.5), 'def': (2.15, -1.15),
    'class': (1.95, -1.5), 'export': (2.1, -1.15),
    'function': (1.7, -0.3), 'func': (1.7, 0.0),
    'const': (1.7, -0.6), 'public': (1.3, 0.0),
    'from': (1.4, -0.25), 'namespace': (1.45, -2.1),
    'void': (1.3, 0.0), 'bool': (1.3, 0.0),
    'using': (1.15, -0.15), 'var': (1.1, -0.55),
    'fn': (1.05, -0.6), 'struct': (1.05, 0.0),
    'type': (0.85, -0.2), 'int': (0.7, 0.0),
    'print': (0.65, 0.0), 'if': (0.5, 0.0),
    'echo': (0.4, 0.0), 'let': (0.6, -0.35),
    'char': (0.6, -0.3), 'package': (0.0, -1.2),
}
LINE_MARKERS = {
    '-': 1.47, '--': 1.27, '*': 0.96, '•': 1.53,
    '·': 0.6, '・': 0.6, '+': 0.72, '—': 0.5, '>': 0.4,
    ' *': 0.96, '-\n': 0.69, '+\n': 0.4, ' *\n': 0.64,
    '///\n': 0.91, '---': 0.23, '```': 0.49,
}


def indentation(width):
    if width <= 8:
        return (0.0, 1.22, 0.74, 2.0, 0.45,
                0.82, 0.15, 1.28, -0.24)[width]
    if width > 24:
        return -0.3
    if width % 4 == 3:
        return 2.0 * 0.67 ** ((width - 3) / 4)
    if width % 4 == 1:
        return 0.82 * 0.45 ** ((width - 5) / 4)
    return -0.2


def step(carry, prefix, upstream):
    doc, s = prefix.document_ids[-1], prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    pos = 0 if start else carry[2] + 1
    line_open = not start and carry[1]
    opening = line_open or start
    v = CODE_WORDS.get(s, (0.0, 0.0))[0 if opening else 1]
    if opening:
        if s and s == ' ' * len(s):
            v = indentation(len(s))
        elif s and s == '\t' * len(s):
            v = max(-0.25, 0.74 - 0.25 * (len(s) - 1))
        elif s in LINE_MARKERS:
            v = LINE_MARKERS[s]
        elif s and set(s) == {'#'}:
            v = 1.35 if len(s) == 1 else 0.91
        elif s.startswith('#') and (s[1:].isalpha() or s == '#['):
            v = 1.1
        elif s.rstrip('\r\n') in ('//', '///', '/*', '/**'):
            v = 1.5
        elif s.strip() in ('"""', "'''"):
            v = 0.9
        elif s.rstrip('\r\n') in ('{', '}'):
            v = 0.4
        elif s.startswith(' ') and s.isspace() and '\n' in s:
            v = 0.5 if len(s.rstrip('\r\n')) <= 8 else -0.2
        if start:
            v *= 0.6
        elif v > 0.1:
            v *= 0.94 + 0.41 / (1.0 + pos / 16.0)
    else:
        if s and set(s) == {'#'}:
            v = -0.8 if len(s) == 1 else -0.9
        elif s == '  ':
            v = -0.35
        elif s == '*':
            v = -0.12
        elif s == '@':
            v = -0.37
    if s == '://':
        v = 0.96
    elif s == '\t\n':
        v = 0.72 if line_open else 0.38
    elif s.endswith('\n') and s.lstrip().startswith('{'):
        v = 0.22 if not line_open else 0.55
    return (doc, s.endswith(('\n', '\r')), pos), float(v)

programs.haiku:
"""First token of a line, when it is indentation or a code/markup opener, gets a positive value.

Line-start tokens only: the previous token must end in a newline. Leading whitespace fires
most for 3 spaces, and list bullets and comment markers fire too. Other tokens stay at 0.
"""

READS = ()

# Leading-whitespace tokens, by how many spaces they hold (token strings as the tokenizer splits them).
SPACES = {1: 1.2, 2: 0.7, 3: 2.0, 4: 0.5, 5: 0.8, 7: 1.3, 11: 0.9, 15: 0.7, 19: 0.4}
TABS = {1: 0.7, 2: 0.5}
# Bullets, dashes and comment markers.
MARKERS = {"-": 1.5, "•": 1.5, "*": 0.9, "+": 0.7, "#": 1.4, "##": 1.0, "###": 0.9, "####": 0.9,
           "//": 1.4, "///": 1.7, "--": 1.3, "#[": 1.2, "```": 0.5, ">": 0.5}
# Code and document openers.
KEYWORDS = {"import": 2.4, "from": 1.6, "def": 2.2, "class": 1.9, "const": 1.8, "public": 1.2,
            "using": 1.3, "#include": 1.1, "export": 0.5, "://": 1.0}


def step(carry, prefix, upstream):
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    if "\n" not in prefix.token_strings[-2]:
        return carry, 0.0
    tok = prefix.token_strings[-1]
    if tok and set(tok) == {" "}:
        return carry, SPACES.get(len(tok), 0.0)
    if tok and set(tok) == {"\t"}:
        return carry, TABS.get(len(tok), 0.0)
    return carry, MARKERS.get(tok, KEYWORDS.get(tok, 0.0))

programs.luna:
"""Detect indentation and list markers at the start of a line."""
READS = ()

HORIZONTAL = " \t"
LIST_MARKERS = {"-", "-\n", "•", "*", "+", "—"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[1] != document:
        line_start = True
    else:
        line_start = carry[0]

    value = 0.0
    if line_start and token and token.strip(HORIZONTAL) == "":
        width = len(token)
        value = {1: 1.1, 2: 0.8, 3: 1.9,
                 4: 0.85, 7: 1.3}.get(width, 1.4)
    elif line_start and token in LIST_MARKERS:
        value = {"-": 1.5, "-\n": 0.6, "•": 1.7, "*": 1.1,
                 "+": 0.6, "—": 0.45}[token]
    elif line_start and token in {"#", "###"}:
        value = 1.1 if token == "#" else 0.9
    elif line_start and token == "import":
        value = 2.4
    elif token == "://":
        value = 1.2
    elif token == "/*":
        value = -0.65

    if "\n" in token or "\r" in token:
        tail = token[max(token.rfind("\n"), token.rfind("\r")) + 1:]
        next_line_start = tail.strip(HORIZONTAL) == ""
    elif token and token.strip(HORIZONTAL) == "":
        next_line_start = line_start
    else:
        next_line_start = False
    return (next_line_start, document), value

"""Spot end-of-text and comma/semicolon separators at the end of a line."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token == "<|endoftext|>":
        return None, 1.4
    if token.lstrip().startswith((",", ";")) and "\n" in token:
        return None, -1.8
    return None, 0.0

programs.sol:
"""Recognize zero at the beginning of a digit sequence, not inside it.

A zero after an opening bracket is strong; after a decimal point or comma
it is weaker. Whitespace separates numbers, but a space immediately after
a digit still dampens the response. Nonzero tokens are nearly silent.
ASCII and fullwidth zero share these rules; subscript zero is predicted
at 0.45. The two previous tokens are remembered within a document only.
"""
READS = ()


def digit_end(text):
    return bool(text) and text[-1].isdecimal()


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != document:
        previous = earlier = ""
    else:
        _, previous, earlier = carry
    state = (document, token, previous)
    value = 0.002
    if token == "₀":
        value = 0.45
    elif token in ("0", "０"):
        if not previous:
            value = 0.105
        elif digit_end(previous):
            if previous in ("0", "０"):
                value = -0.02 if digit_end(earlier) else 0.06
            else:
                value = -0.008
        elif previous.isspace():
            if digit_end(earlier) and "\n" not in previous and "\r" not in previous:
                value = 0.48
            elif earlier.strip().isalpha():
                value = 0.94
            else:
                value = 0.88
        elif previous.endswith("."):
            value = 0.745 if digit_end(earlier) else 1.03
        elif previous.endswith((",", "，")):
            value = 0.63
        elif previous.endswith(":"):
            value = 0.71
        elif previous.endswith(("(", "[", "{")):
            value = 0.98 if previous[0].isspace() else 1.07
        elif previous.endswith("/"):
            value = 0.95
        elif previous.endswith("-"):
            value = 0.91
        else:
            value = 0.84
    return state, value

"""Detect a spelling family around token-final 'is', not the meaning 'be'.

Short -is fragments generally receive large positive predictions. Case,
leading space, length, and preceding vowels determine their strength;
-sis and -xis endings are weaker. Ordinary is/was/his, apostrophe-s,
-isn, doubled-s, consonant-ys, and Cyrillic ис have separate small rules.
'This' and plural abbreviations such as APIs are excluded. Other tokens
get zero. The sole contextual rule suppresses apostrophe-s after 'let',
with context reset at document boundaries. Irregular lexical responses
and other context-dependent variation are deliberately left unmodeled.
"""
import string

READS = ()


def response(token, previous=''):
    word = token.strip()
    low = word.lower()
    spaced = token.startswith(' ')
    # Ignore punctuation attached before a whole-word exception.
    bare = low.lstrip(string.punctuation + '“')
    if bare == 'this':
        return 0.0
    if word in ("'s", '’s'):
        return -0.08 if previous.strip().lower() == 'let' else 0.72
    if low == 'was':
        return 0.75 if spaced else 1.1
    if low == 'his':
        if word == 'HIS':
            return 3.1
        return 1.1 if spaced else 1.9
    if low == 'is':
        if word == 'Is':
            return 1.0
        if word == 'IS':
            return 2.5 if spaced else 4.0
        return 0.96 if spaced else 3.0
    if low.endswith('is'):
        # Lowercase plural s following an uppercase abbreviation.
        if (word.endswith('Is') and len(word) >= 3
                and word[-3].isupper()):
            return 0.0
        if bare == 'is':
            return 1.2 if word.endswith('Is') else 2.2
        n = len(low)
        if low == 'bis':
            return 4.8
        if low.endswith('sis'):
            if word.isupper():
                return 2.5
            return 1.4 if n <= 4 else 1.0 if n <= 7 else 0.65
        if low.endswith('xis'):
            return 0.85 if spaced else 1.2
        vowel_before_is = low[-3] in 'aeou' and not low.endswith('quis')
        if vowel_before_is:
            if n == 3:
                return 2.6
            return 0.8 if spaced or n >= 5 else 1.4
        if n == 3:
            return 3.4
        if spaced:
            return max(0.4, 2.1 - 0.35 * (n - 4))
        return max(0.4, 3.4 - 0.5 * (n - 3))
    if low.endswith('iss'):
        return 0.7
    if low == 'isn':
        return 0.36
    if low.endswith('ys'):
        if len(low) == 2:
            return 0.85
        if low[-3] not in 'aeiou':
            return 0.6 if low == 'sys' else 2.4 if len(low) == 3 else 1.0
    if low.endswith('ис'):
        return 2.1 if len(low) == 2 else 1.4 if len(low) == 3 else 0.65
    if low in ('ís', 'ıs'):
        return 1.9
    return 0.0


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), response(token, previous)

programs.haiku:
"""Layer 0, MLP down-projection component 4505: the spelled-out sound "is".

What it responds to: the token that carries the English copula "is" (or its
clipped forms "'s" and "was"), and short word pieces whose spelling ends in
"is" (bis, dis, mis, ris, vis, IS, Paris, ...). The strongest response is to
"is" glued inside a word (e.g. "bis" in "perpendicular bisector", "dis" in
"disposition"), a moderate one to a free-standing " is", and almost none to
"this" or to ordinary function words.

The program does not look at context: each position is scored from the
token alone, with the values read off the training data (mean activation per
token type). "'s" after "let" is the one exception, since "let's" is not "is".
"""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    space = token[:1] == " "
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if token == "is":
        value = 3.0  # "is" glued inside a word, e.g. "bis"+"ector"
    elif token == "IS":
        value = 3.9
    elif token == " is":
        value = 1.0  # a free-standing copula "is"
    elif token == " IS":
        value = 2.6
    elif token == " his":
        value = 1.0
    elif lower in ("'s", "’s"):
        value = 0.0 if prev == "let" else 0.75  # "it's", "there's"; not "let's"
    elif lower == "was":
        value = 0.75 if space else 1.3
    elif token == "ис":
        value = 2.1  # Cyrillic spelling of the same sound
    elif lower.endswith("is") and lower != "this" and not space and len(lower) <= 4:
        value = 2.5  # short word piece ending in "is"
    elif lower.endswith("is") and lower != "this" and space and len(lower) <= 5:
        value = 2.0  # short spaced word ending in "is": " Paris", " Dis"
    elif lower.endswith("is") and lower != "this":
        value = 0.8  # longer words: analysis, basis, axis
    else:
        value = 0.0
    return None, float(value)

programs.luna:
"""Mark common English linking verbs and possessive forms.

This component often adds a positive pulse on "is" and "was", and on
possessive "'s" and "his". Other tokens are left at zero.
"""
READS = ()

COPULAS = {"is": 0.95, "was": 0.78}
POSSESSIVES = {"'s": 0.62, "’s": 0.78, "his": 1.12}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in COPULAS:
        value = COPULAS[word]
    else:
        value = POSSESSIVES.get(word, 0.0)
    return None, float(value)

programs.sol:
"""A lexical detector of broad choices, quantified sets, and exclusions.

But/except fire directly, especially in all/nothing/anything-but phrases.
Nearby quantifiers boost listed words for alternatives and unspecified
objects or qualities. Partitive 'of' has the opposite sign after all/each.
Two decaying scope cues track this local context; documents and sentences
reset them. At the first token, all itself instead has a negative response.
The word lists approximate these patterns, not unrestricted semantic parsing.
"""
READS = ()

SCOPE = {
    'all': 1.0, 'every': 0.7, 'any': 0.6, 'no': 0.5,
    'each': 0.3, 'some': 0.12, 'many': 0.14, 'few': 0.1,
    'nothing': 0.7, 'anything': 0.7, 'everyone': 0.7,
    'everything': 0.8, 'anywhere': 0.65, 'everywhere': 0.55,
    'anyone': 0.65, 'anybody': 0.65, 'nobody': 0.75,
    'none': 0.5, 'last': 0.4, 'whatever': 0.4,
}
# Gains for the fast-decaying cue: alternatives, general objects,
# qualifications, reference words, and conventional "all" phrases.
RESPONSE = {}
for words, weight in (
    ('other others possible possibilities conceivable imaginable', 2.8),
    ('real relevant meaningful necessary practical significant previous', 2.3),
    ('thing things life', 2.5),
    ('way ways kinds sorts', 1.8),
    ('kind sort', 1.5),
    ('form forms sense reason idea doubt solution solutions chance', 1.8),
    ('need means sign signs questions question more less potential', 1.5),
    ('number amount instances', 1.5),
    ('given subsequent existing future prior major smaller', 1.8),
    ('new earlier later', 0.9),
    ('like outside', 1.8),
    ('these those who', 1.5),
    ('one single individual', 1.5),
    ('two three four five six seven eight nine ten', 0.6),
    ('your you', 0.5),
    ('else', 1.3),
    ('that about', 0.85),
    ('type types', 0.5),
    # All right / all rights / All Saints / All Souls.
    ('right rights saints souls', 2.0),
    ('time times', 0.7),
    ('manner', 4.4),
):
    for word in words.split():
        RESPONSE[word] = weight
PARTITIVE = {
    'all': -2.07, 'each': -0.55, 'some': -0.4, 'both': -0.8,
    'many': -0.3, 'few': -0.15, 'none': -0.25, 'most': -0.25,
}
WEAK_SCOPE = {
    'other': 0.25, 'different': 0.15, 'more': 0.2, 'less': 0.2,
    'few': 0.17, 'many': 0.2, 'those': 0.16, 'these': 0.1,
    'of': 0.06, 'only': 0.12, 'not': 0.1, 'without': 0.15,
}
CONTRAST = {'mais', 'pero', 'aber', '但是', '但'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    previous, scope, broad = ('', 0.0, 0.0) if fresh else carry[1:]
    token = prefix.token_strings[-1]
    spelling = token.strip()
    word = spelling.lower()
    value = RESPONSE.get(word, 0.0) * broad

    if word in {'but', '-but'}:
        base = 1.61 if spelling in {'but', '-but'} else 0.83
        if spelling == 'But' and token.startswith(' '):
            base = 0.94
        elif spelling == 'BUT':
            base = 1.1
        value = base + 5.2 * scope
    elif word == 'except':
        value = 1.05 + 3.3 * scope
    elif word in CONTRAST:
        value = 0.5
    elif word == 'но' and token.startswith(' '):
        value = 0.55
    elif word == 'such':
        value = min(2.0, 3.8 * broad)
    elif word == 'of':
        value = PARTITIVE.get(previous, 0.0)
        if previous in {'manner', 'sense'}:
            value += 3.0 * scope
        elif previous in {'kind', 'kinds', 'sorts', 'form', 'number', 'instances'}:
            value += 2.0 * scope
    elif word == 'case' and previous in SCOPE:
        value = -1.3 if previous == 'any' else -0.6
    elif word == 'cases' and previous in {*SCOPE, 'most', 'both'}:
        value = -0.25 - 0.45 * SCOPE.get(previous, 0.12)
    elif word == 'rights' and spelling == 'rights':
        value = broad
    elif word in {'time', 'times'} and previous == 'every':
        value = 0.3
    elif word == 'unless':
        value = 0.25

    if fresh and word == 'all':
        value = -1.5 if spelling == 'all' else -1.7
        if token == 'All':
            value = -2.08
    elif fresh and word == 'but':
        value = 1.0 if token.startswith(' ') else 0.75
        if spelling == 'But':
            value -= 0.1 if token.startswith(' ') else 0.12

    if any(c in token for c in '.!?;\n'):
        scope = broad = 0.0
    else:
        scope *= 0.45 if ',' in token else 0.65
        broad *= 0.3
    cue = SCOPE.get(word, 0.0)
    if token == 'all' and not fresh:
        cue *= 0.7
    scope = max(scope, cue)
    broad = max(broad, 0.0 if word == 'last' else cue,
                WEAK_SCOPE.get(word, 0.0))
    return (doc, word, scope, broad), float(value)

"""First-person statements, approximated with a short grammatical window.

Listed predicates after 'I' produce negative values: strongest for wants,
thoughts and feelings, weaker for past actions. Adverbs, negation, auxiliaries
and -ing forms extend this short grammatical window. Whitespace, case and
document position adjust its strength; conditional/question leads weaken it.
Also recognize 'let me' and several other languages' first-person forms.
Small lexical offsets cover cognition words outside this context. Otherwise
predict zero, intentionally omitting incidental identifier and rare-token
responses. All state resets at document boundaries.
"""
import re

READS = ()
THOUGHTS = set('think know believe feel guess wonder hate'.split())
WISHES = {'hope', 'wish'}
PRESENT_AUX = set('have don dont do need'.split())
MENTAL_STATES = set('see love understand remember suppose assume hear '
                    'heard doubt'.split())
MODALS = set('can cannot cant will would must'.split())
PAST_REPORTS = set('watched realized remembered recalled finished tested '
                   'modified created'.split())
PAST = set('was had could should did didn couldn haven thought knew felt '
           'took went put used loved liked'.split())
ACTIONS = set('get got find found try tried made mean agree realize notice '
              'noticed saw read came look take go use live keep imagine wanted '
              'like fear suspect apologize appreciate disagree bet swear miss '
              'prefer suggest seem chose forgot accept assure write welcome '
              'recall trust dare play dream'.split())
ADVERBS = set('just really also still always never already personally honestly '
              'now actually probably recently currently simply truly finally '
              'once perhaps'.split())
CONTRACTIONS = {"'m": 3.55, "'ve": 3.2, "'ll": 2.0, "'d": 1.45}


def predicate(word):
    if word in CONTRACTIONS:
        return CONTRACTIONS[word]
    if word == 'want':
        return 3.7
    if word in THOUGHTS or word == 'personally':
        return 3.25
    if word in WISHES or word in PRESENT_AUX:
        return 2.85
    if word in MENTAL_STATES or word in ('am', 'wanna'):
        return 2.4
    if (word in MODALS or word in ACTIONS or word in ADVERBS
            or word.endswith('ing')):
        return 1.65
    if word in PAST_REPORTS or word in ('shall', 'wouldn', 'won'):
        return 1.25
    return 1.0 if word in PAST else 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    word = token.strip().replace('’', "'").lower()
    previous, age, strength, position = '', 4, 1.0, 0
    if carry is not None and carry[0] == doc:
        _, previous, age, strength, position = carry
        age, position = min(age + 1, 4), position + 1
    value = 0.0
    if re.search(r'(^|[^a-z0-9_])i$', word):
        value, age = 0.07, 0
        strength = 0.95 if token[:1].isspace() else 1.25
        if token.strip().endswith('i'):
            strength = 1.05
        if position < 4:
            strength *= 1.2
        if previous in {'if', 'when', 'whether', 'can', 'could', 'should', 'do', 'did'}:
            strength *= 0.6
    elif age == 1:
        value = -strength * predicate(word)
        if '’' in token:
            value *= 0.88
        if token[:1].isalpha():
            value *= 0.5
    elif age == 2:
        if previous in ADVERBS:
            value = -0.6 * strength * predicate(word)
        elif previous in ('don', 'can', 'cannot', 'didn', 'couldn', 'haven',
                          'wouldn', 'won', 'do'):
            if word in ("'t", 'not'):
                value = -strength * (2.9 if previous == 'don' else 1.6)
        elif previous in ('am', "'m"):
            value = (-2.3 if word in {'not', 'afraid', 'unable', 'aware', 'sure',
                                          'curious', 'unsure', 'wondering', 'trying'}
                     else -1.4 if word.endswith('ing')
                     else -0.8 if word.isalpha() else 0.0)
        elif previous in ('would', "'d") and word == 'like':
            value = -1.5
        elif word == 'to' and previous in ('want', 'need', 'have'):
            value = -1.5 if previous == 'want' else -0.7
        elif previous in ('have', "'ve"):
            value = (-1.0 if word == 'been' else -0.7
                     if word in {'a', 'an', 'the'} else -0.4 * predicate(word))
    elif age == 3 and previous in ('don', 'can', 'do', "'t"):
        if word in ("'t", 'not'):
            value = -1.7 * strength
        elif previous == "'t":
            value = -0.3 * predicate(word)
    elif age == 3 and previous in ADVERBS and word.endswith('ing'):
        value = -0.9
    elif word in ('me', 'myself'):
        value = -0.9 if previous == 'let' else -0.35
    elif word.startswith('我') and not word.startswith(('我们', '我們')):
        value = -0.65 if word == '我' else -0.45 if word == '我的' else -1.2
        if '想' in word:
            value = -2.6
    elif word in ('想', '想要'):
        value = -0.9
    elif word in ('私は', '나는', 'меня', 'moi'):
        value = -0.7
    elif previous in ('je', 'j') and word in ('suis', "'ai"):
        value = -1.0
    elif word in {'think', 'believe', 'hope', 'guess', 'thought', 'doubt'}:
        value = 0.28
    elif word in {'know', 'known', 'knew', 'understand'}:
        value = -0.17
    elif word == "'t":
        value = -0.16
    return (doc, word, age, strength, position), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:4508 -- "the speaker's own predicate" detector.

This component is almost always silent. When it fires, it goes strongly negative on the
word right after a first-person "I" ("I'm", "I think", "I want", "I have", "I am",
"I don't"), i.e. on the verb or auxiliary that states the speaker's own state, belief or
intention. The sizes below are typical activations, read off training text:

- verbs and auxiliaries of the speaker's state/belief/intent ("'m", "am", "'ve", "want",
  "think", "know", "believe", "feel", "hope", "have", "need", "do", "don"): about -3.
- modals, past-tense and other verbs ("could", "would", "can", "had", "got", "wanted"):
  about -1.7.
- any other plain word after "I": about -0.4 (punctuation and symbols: 0).
- a negation two words after "I" ("I don't", "I'm not", "I can't"): about -2.
- "let me": about -0.9, "let's": about -0.5; "want to": "to" about -0.5.
- the word after "we": about -0.4.
- when "I" sits in a question or an "if/when" clause ("Do I", "If I", "When I"), the
  activation is weaker (about 0.6 of the above).

Everything else is 0. The component's activation is concentrated in these cases; the rest
of its variance is diffuse small values that this program does not capture.
"""

READS = ()

# First-person subject forms (lower- and upper-case, with and without a leading space).
I_FORMS = {"I", " I", "i", " i", '"I', "“I", "…I", ":I"}
WE_FORMS = {" we", " We", "We"}
LET_FORMS = {" let", " Let", "Let", "let"}
WANT_FORMS = {" want", " wants", " wanted"}
# Words that, just before "I", turn it into a question or "if/when" clause.
QUESTION_WORDS = {" if", " when", " do", " Do", " how", " How", " what", " What", " why",
                  " where", " did", " Did", " should", " can"}
# Speaker's state, belief and intention verbs and present-tense auxiliaries.
STRONG = {"'m", "’m", "'ve", "’ve", " am", " want", " believe", " feel", " know", " think",
          " don", " see", " hope", " have", " need", " do", " wish", " love", " understand"}
# Modals, past tense and other verbs.
MID = {" can", " cannot", " would", " will", " could", " should", " must", " did", " had",
       " made", " found", " got", " get", " wanted", " just", "'ll", "’ll", "'d", "’d", " really"}
NEGATION = {"'t", "’t", " not", "n't"}


def step(carry, prefix, upstream):
    s = prefix.token_strings
    cur = s[-1]
    prev = s[-2] if len(s) > 1 else ""
    prev2 = s[-3] if len(s) > 2 else ""
    is_word = cur.strip().isalpha()

    if prev in I_FORMS:
        # The word right after "I".
        scale = 0.6 if prev2 in QUESTION_WORDS else 1.0
        if cur in STRONG:
            return None, -3.2 * scale
        if cur in MID:
            return None, -1.7 * scale
        return None, (-0.4 * scale if is_word else 0.0)
    if prev2 in I_FORMS and cur in NEGATION:
        # "I don't", "I'm not", "I can't": the negation two words after "I".
        return None, -2.0
    if prev in WANT_FORMS and cur == " to":
        return None, -0.5
    if prev in WE_FORMS and is_word:
        return None, -0.4
    if prev in LET_FORMS:
        if cur == " me":
            return None, -0.9
        if cur in ("'s", "’s"):
            return None, -0.5
    return None, 0.0

programs.luna:
"""Approximate the component's strong first-person response: common words
following I get a negative prediction, with smaller cues for other forms."""
READS = ()

PREDICATES = {
    "am", "'m", "'ve", "'ll", "'d", "have", "had", "do", "did",
    "don", "didn", "can", "could", "will", "would", "must", "was",
    "think", "believe", "know", "see", "feel", "hear", "hope", "want",
    "need", "mean", "find", "found", "remember", "suppose", "guess",
    "understand", "assume", "agree", "try", "trying", "tried", "share",
    "come", "came", "look", "like", "love", "make", "made", "get", "got",
    "say", "said", "tell", "told", "go", "went", "take", "thought",
    "hate", "apologize", "personally", "sorry", "currently", "always",
}

SELF_PRONOUNS = {"我", "나는"}
NEGATION_AUXILIARIES = {"don", "doesn", "didn", "isn", "aren", "wasn", "weren",
                        "haven", "hasn", "hadn", "can", "couldn", "won", "wouldn",
                        "shouldn", "mustn"}


def word(text):
    return text.strip().lower().replace("’", "'")


def step(carry, prefix, upstream):
    """Use the previous word to spot first-person predicates and contractions."""
    t = prefix.position
    current = word(prefix.token_strings[-1])
    if t > 0 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = word(prefix.token_strings[-2])
        if previous == "i":
            if current in PREDICATES:
                return None, -2.3
            return None, -0.25
        if previous == "let" and current == "me":
            return None, -0.8
        if previous in NEGATION_AUXILIARIES and current == "'t":
            return None, -1.0
    if current in SELF_PRONOUNS:
        return None, -0.6
    return None, 0.0

programs.sol:
"""Predict a mixed detector of short lexical stems, not one semantic category.

Large positive responses go to numerical shorthand (min/max/sum/num/mod),
Git/bin, and man/men. Smaller responses cover car/war, figure abbreviations,
and other short words. Three-letter consonant-vowel-consonant spellings get
a small vowel-dependent background response, excluding common function words.

Leading spaces and code delimiters are ignored. Matching uses the current
TOKEN, so ' car' also fires inside 'carboxy...'. Attached lowercase man/men
and attached car/war are weaker. The only phrase rule is an echo on 'of' in
'sum of'. Most detailed contextual and negative responses are not modeled.
"""
READS = ()

SEPARATORS = ' \t\r\n._/\\({["\'-=<>:,;'
VOWELS = set('aeiou')
CONSONANTS = set('bcdfghjklmnpqrstvwxyz')
FUNCTION_WORDS = set('''
    the for and but nor not can may had has was did got get let
    her his she its who how why yet yes now per von des del les
    los das der den dem als mit que las con por par sur est une
    aux non ces cet ses mes tes nos vos son mon ton
'''.split())


def lexical_value(raw, attached=False):
    word = raw.lstrip(SEPARATORS)
    w = word.lower()
    if w in {'max', 'num'}:
        return 0.73
    if w == 'min':
        return 0.67
    if w == 'sum':
        return 0.58
    if w == 'mod':
        return 0.48
    if w in {'bin', 'git'}:
        return 0.69
    if w == 'nil':
        return 0.44
    if w == 'hex':
        return 0.50
    if w == 'nan':
        return 0.30
    if w in {'man', 'men'}:
        return 0.33 if attached and word.islower() else 0.67
    if w in {'guy', 'guys', 'sir', 'kin'}:
        return 0.38
    if w in {'woman', 'women', 'him'}:
        return 0.16
    if w in {'car', 'war'}:
        return 0.60 if not attached else 0.48
    if w in {'cars', 'wars'}:
        return 0.40
    if w == 'fig':
        return 0.57 if word.isupper() else 0.26
    if w in {'sin', 'dim'}:
        return 0.40
    if w in {'cos', 'tan'}:
        return 0.20
    if w == 'tax':
        return 0.37
    if w in FUNCTION_WORDS:
        return 0.01
    if (len(w) == 3 and w[0] in CONSONANTS
            and w[1] in VOWELS and w[2] in CONSONANTS):
        value = 0.11 if w[1] in 'ai' else 0.04
        if w[1] == 'e':
            value = 0.015
        return value * (0.6 if attached else 1.0)
    if w.startswith(('max', 'github')):
        return 0.16
    if w in {'minimum', 'minimal', 'minutes', 'minute', 'mode'}:
        return 0.12
    if raw == w and len(w) == 2 and w[0] in VOWELS and w[1] in 'mn':
        return 0.09
    return -0.003


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    attached = bool(previous and previous[-1].isalpha()
                    and raw and raw[0].isalpha())
    value = lexical_value(raw, attached)
    # The short phrase "sum of" has a weaker echo on its preposition.
    if raw.lower() == ' of' and previous.strip().lower() == 'sum':
        value = 0.18
    return (doc, raw), value

"""A mostly orthographic detector for compact rn-ending stems.

Turn, born, corn and short fragments such as ern have large negative
responses. Visible endings dilute this response. Common whole words
(return, modern, morning, etc.) are exceptions, not a general rn topic.
Weaker rules cover compact consonant+n fragments and explicit RNA, brown,
and birth/turn forms. An inflection or short vowel ending after an rn-containing
token retains a small negative echo. Only adjacent tokens are inspected.
"""
import re

READS = ()
QUIET_STEMS = {'return', 'modern', 'pattern', 'attern', 'western',
               'eastern', 'morn'}
WEAK_STEMS = {'warn', 'worn', 'porn', 'forn', 'yarn'}
BIRTH_TURN = {'birth', 'births', 'newborn', 'spawn', 'bear', 'bears',
              '天生', '出生', '诞生', '转', '轉', '转动'}
ENDINGS = {'': 1.0, 's': 0.95, 'ed': 0.7, 'ing': 0.65,
           'e': 0.55, 'a': 0.8, 'o': 0.4, 'er': 0.2,
           'ers': 0.3, 'al': 0.08, 'el': 0.13, 'els': 0.13, 't': 0.55}


def response(token):
    word = token.strip().lower().lstrip('._-')
    if word in BIRTH_TURN:
        return -1.0
    if word in {'brown', 'rna', 'mrna'}:
        return -0.3 if word == 'mrna' else -1.1
    if not re.fullmatch('[a-z]+', word):
        return 0.0
    if 'rn' not in word:
        if re.fullmatch('[bcdfghjklmnpqstvwxz]{1,2}n', word):
            return -0.75
        if re.fullmatch('[aeou][hklmz]n|enn', word):
            return -0.9
        return 0.0
    before, _, ending = word.partition('rn')
    stem = before + 'rn'
    if stem in QUIET_STEMS or len(stem) > 7:
        return 0.0
    if stem in {'earn', 'learn'}:
        strength = 1.6 if stem == 'earn' else 1.15
    elif stem in WEAK_STEMS:
        strength = 1.5 if stem == 'yarn' else 2.3
    elif len(stem) <= 4:
        strength = {'arn': 3.0, 'ern': 3.9, 'orn': 4.2,
                    'urn': 4.4}.get(stem[-3:], 2.5)
        if stem in {'arn', 'orn', 'urn'}:
            strength += 1.1
        if stem == 'corn':
            strength = 5.1
        if stem == 'orn' and token[:1].isspace():
            strength = 3.0
    elif stem in {'intern', 'extern', 'supern', 'churn'}:
        strength = 3.6
    elif stem.endswith('tern') and len(stem) <= 6:
        strength = 3.5
    else:
        strength = 1.8 if len(stem) <= 6 else 0.5
    if ending in {'ing', 'ings'} and stem in {'learn', 'warn'}:
        factor = 0.16
    elif ending == 'ed' and stem == 'earn':
        factor = 1.1
    elif ending == 'ings' and stem == 'earn':
        factor = 0.65
    elif stem == 'turn' and ending in {'out', 'over', 'around'}:
        factor = 0.5
    else:
        decay = 0.65 if len(stem) <= 4 else 0.25
        factor = ENDINGS.get(ending, decay ** len(ending))
    return -strength * factor


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = response(token)
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2].lower()
        if token.lower() in {'s', 'es', 'ed', 'ing', 'er', 'ers',
                              'a', 'e', 'i', 'o', 'os', 'ar'}:
            if 'rn' in previous and previous[-1:].isalpha():
                fraction = 0.25 if token.lower() in {'s', 'er'} else 0.2
                if token.lower() == 's' and previous.strip().endswith('turn'):
                    fraction = 0.55
                value = min(value, fraction * response(previous))
        if token[:1].isalpha():
            tail = re.search('[a-z]+$', previous)
            joined = (tail[0] if tail else '') + token.lower()
            if joined in QUIET_STEMS:
                value *= 0.35
            elif joined in {'newborn', 'stubborn'}:
                value *= 0.55
    return None, float(value)

"""A mostly local detector for the letter x, in variables, words and code.

Short fragments ending in 'ex' have a much larger response than full words.
The estimate distinguishes isolated x, other final x, and initial x.
Joining x to earlier letters increases its response; 'for example' reduces
it. The multiplication sign, Cyrillic 'кс'/'х', and Arabic 'خ' receive
related responses, as does '-ccess-' (access/success). Six-related number
words and French '-eux' endings are weak exceptions. Special markers and
byte escapes are excluded. Other text gets a small baseline.
"""

READS = ()
SIX_NUMERALS = {'six', 'sixth', 'sixteen', 'sixteenth', 'sixty', 'sixtieth'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = ''.join(c for c in token.lower() if c.isalpha())
    n = len(word)
    same_doc = (len(prefix.document_ids) > 1 and
                prefix.document_ids[-1] == prefix.document_ids[-2])
    previous = prefix.token_strings[-2].strip() if same_doc else ''
    if token.startswith('<|') or (token.startswith('\\x') and n > 1):
        value = 0.0
    elif 'x' in word:
        if word == 'x':
            value = 1.26 if 'X' in token else 1.03
            if token[:1].isspace():
                value -= 0.18
            elif token[:1] in 'xX' and previous and previous[-1].isalpha():
                value += 0.65
            elif previous.isdigit():
                value -= 0.15
        elif word.endswith('ex'):
            value = 5.0 if n == 2 else 3.8 if n <= 4 else 1.5
            if word == 'ex' and token.isalpha():
                value += 0.8
            if word == 'ex' and 'E' in token:
                value -= 0.75
            if word.endswith('lex') and n == 3:
                value += 1.3
        elif word.endswith('x'):
            value = 1.8 if n == 2 and word[-2] in 'aeiou' else 1.5
            if n >= 5:
                value = 0.95
        elif word.startswith('x'):
            value = 0.6 if n == 2 else 0.9
        elif word.startswith('ex') and n == 3:
            value = 2.1
        else:
            value = 1.1
        if word in SIX_NUMERALS:
            value = 0.3 + (0.3 if any(c.isupper() for c in token) else 0.0)
        elif word.endswith('eux'):
            value = 0.2 if token[:1].isspace() else 0.65
        elif word == 'example':
            value = 0.85
            if previous.lower() == 'for':
                value = -0.1 if previous == 'For' else 0.06
    elif '×' in token:
        value = 0.71
    elif 'кс' in word:
        value = 4.8 if word == 'екс' else 1.3
    elif 'х' in word:
        value = 0.4
    elif 'خ' in word:
        value = 2.2 / max(1, n - 1)
    elif 'ccess' in word:
        value = 0.8
    else:
        value = 0.007
    return None, float(value)

