programs.sol:
"""A spelling heuristic for short, word-internal continuations.

An unspaced vowel-led fragment following a consonant-final fragment is
positive, especially for i/u; complete grammatical endings are weak.
Named learned-word stems give stronger, length-dependent responses.
Split Fig./Eq., OBSERVATION and math-font spellings are separate cases.
This remembers only the previous token, reset at document boundaries;
it does not recognize every word or reconstruct token-specific variation.
"""
import re
import unicodedata

READS = ()
VOWELS = frozenset('aeiouyаеёиоуыэюя')
INFLECTIONS = frozenset(('s', 'es', 'ed', 'ing', 'er', 'ers', 'est', 'ly'))
# Right-hand strings begin continuations in familiar learned word families.
U_STEMS = {
    'cell': 'ul', 'comm': 'u', 'consec': 'u', 'exec': 'ut',
    'config': 'ur', 'fig': 'u', 'form': 'ul', 'glob': 'ul',
    'reg': 'ul', 'sim': 'ul', 'stim': 'ul', 'pop': 'ul',
    'diff': 'us', 'stat': 'ut', 'фиг': 'у',
}
I_STEMS = {
    'def': 'i', 'indef': 'in', 'ident': 'i', 'qual': 'i',
    'orig': 'in', 'ord': 'in', 'init': 'i', 'div': 'i',
    'leg': 'i', 'prelim': 'in', 'sign': 'i', 'spec': 'i',
    'cert': 'i', 'vacc': 'in', 'polit': 'ic', 'const': 'it',
}
# Index 1..5 is the continuation's length, with 5 meaning five or more.
U_BY_LENGTH = (0.0, 1.91, 1.78, 0.69, 0.60, 0.21)
I_BY_LENGTH = (0.0, 1.46, 1.07, 0.54, 0.61, 0.18)


def plain(s):
    return ''.join(c for c in unicodedata.normalize('NFD', s.lower())
                   if unicodedata.category(c) != 'Mn')


def special(p, s, token):
    if p in {'fig', 'figs', 'eq'} and token == '.':
        return 0.36 if p == 'eq' else 0.67
    if p == 'fig' and token == 'S':
        return 0.45
    if p == 'bs' and token == 'ERV':
        return 0.43
    if p == 'math' and s in {'bb', 'bf', 'cal', 'fr', 'scr', 'sf', 'it'}:
        return 0.80
    if p.endswith('math') and s.startswith('em'):
        return 0.86 if len(s) > 6 else 2.59
    if p.endswith('phys') and s.startswith('i'):
        return 2.70 if len(s) == 1 else 1.27 if len(s) <= 3 else 0.07
    if p == 'процед' and s == 'у':  # процедура: procedure
        return 2.21
    # Shared Latin stems: attribute/contribute/distribute, and
    # constitute/institute/substitute. The spelling carries across prefixes.
    if p.endswith(('trib', 'stit')) and s.isalpha() and s.startswith('u'):
        return U_BY_LENGTH[min(len(s), 5)]
    for stems, sizes in ((U_STEMS, U_BY_LENGTH), (I_STEMS, I_BY_LENGTH)):
        ending = stems.get(p)
        if ending and s.isalpha() and s.startswith(ending):
            return sizes[min(len(s), 5)]
    return None


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    match = re.search(r'[^\W\d_]+$', plain(previous))
    p, s = match[0] if match else '', plain(token)
    value = special(p, s, token)
    if value is None:
        value = -0.003
        if s.isalpha() and s[0] in VOWELS and len(p) >= 3:
            if p[-1] in VOWELS:
                value = 0.02
            elif token.istitle() and not previous.strip().isupper():
                value = 0.035
            elif token in INFLECTIONS:
                value = -0.06 if token == 'ing' else (
                    -0.03 if token == 'ed' else 0.04)
            elif len(s) <= 2:
                if len(s) == 1 and s[0] in 'uу':
                    value = 0.55 if len(p) >= 4 else 0.44
                elif s[0] in 'iu':
                    value = 0.40 if len(p) >= 4 else 0.27
                elif s[0] in 'ae':
                    value = 0.22 if len(p) >= 4 else 0.09
                else:
                    value = 0.13 if len(p) >= 4 else 0.07
            elif len(s) == 3:
                value = (0.14 if s[0] in 'ei' else 0.07)
                value += 0.14 if s[-1] == 'a' else 0.0
            else:
                value = 0.025
    return (doc, token), float(value)

programs.luna:
"""Guess positive activations at two textual cues.

Give a small estimate to a short letter token continuing a word split across
tokens, and to a period that follows a figure or equation abbreviation.
"""
READS = ()


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    token = tokens[-1]
    same_doc = len(tokens) > 1 and prefix.document_ids[-1] == prefix.document_ids[-2]
    if same_doc and token == ".":
        previous = tokens[-2].strip().casefold()
        if previous in {"fig", "eq"}:
            return None, 0.2
    if not token or token[0].isspace() or len(token) > 3 or not token.isalpha():
        return None, 0.0
    if same_doc:
        previous = tokens[-2].rstrip()
        if previous and previous[-1].isalpha():
            return None, 0.023
    return None, 0.0

programs.sol:
"""A partial time-expression and phrase-boundary detector.

The largest predictions are negative on Chinese recent-event words, dateline
endings, and their following commas. English time phrases give weaker negative
responses at commas and articles. A few message delimiters have small responses.
The recent-event response is stronger near a document's beginning. Other lexical
responses are not modeled: unrecognized cases stay near zero.
"""
import math
import re

READS = ()


def words(text):
    return frozenset(text.split())


RECENT = words('近日 日前')
DAY_END = words('日电 日電 日消息 日上午 日下午 日晚 日晚间 日晚間 '
                '日至 日在 日内 日凌晨')
DAY_PART = words('上午 下午 傍晚 晚间 晚間')
CALENDAR_EDGE = words('年初 年底 年末 月底 月初 年间 年間 年前 年后 '
                     '年後 年开始 年起')
RELATIVE = words('今年 去年 前年 明年 今天 今日 昨日 昨天 近期 目前 '
                 '当天 當天 当年 當年')
SINCE = words('以来 以來 近年来 近年來 今年以来 多年来')
TIME_BOUNDARY = words('期间 期間 时期 時期 年 月 时 時 后 後 前 之后 '
                     '之後 之前 结束后 过后 以后 以後 暑假 假期')
REPORTING = words('据了解 據了解 据悉 據悉 消息 告诉记者 告訴記者 '
                  '报道 報道 记者 记者从')
LEARNED_NEWS = words('获悉 獲悉')
ANNOUNCE = words('announce announced announcing announces awarded')
ENGLISH_TIME = words(
    'day days week weeks month months year years century morning afternoon '
    'evening night season ago later today yesterday recently lately currently '
    'monday tuesday wednesday thursday friday saturday sunday january february '
    'march april may june july august september october november december')
YEAR = re.compile(r'\b(?:1[5-9]|20)\d{2}[\s,.)]*$')
MARKERS = {'<|endoftext|>': -0.022, '<|im_end|>': -0.04,
           '<|im_start|>': 0.009, '<think>': 0.086, '</think>': -0.036}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    position, previous, tail = 0, '', ''
    if carry is not None and carry[0] == doc:
        _, position, previous, tail = carry
        position += 1
    token = prefix.token_strings[-1]
    s, prev = token.strip(), previous.strip()
    word, last = s.lower(), prev.lower()
    early = math.exp(-position / 20.0)
    value = 0.0014

    for group, response in ((DAY_END, -0.65), (DAY_PART, -0.28),
                            (CALENDAR_EDGE, -0.18), (RELATIVE, -0.08),
                            (REPORTING, -0.23), (LEARNED_NEWS, -0.85)):
        if s in group:
            value = response
    if s in RECENT:
        value = -1.05 - 0.40 * early if s == '近日' else -0.9 - 0.87 * early
    elif s == '日':
        value = -0.14
    elif s in {'正值', '截至目前'}:
        value = -0.42
    elif word in ANNOUNCE:
        value = -0.28
    elif word == 'born':
        value = -0.05 if token.startswith(' ') else -0.16
    elif word in {'recently', 'lately', 'yesterday'}:
        value = -0.07

    # A temporal adjunct ends here: "6月18日，" or "last week,".
    if s.startswith('，'):
        if prev in RECENT:
            value = -0.87 - 0.77 * early
        elif prev == '日' or prev in DAY_END:
            value = -0.58 - 0.22 * early
        elif prev in SINCE | CALENDAR_EDGE | DAY_PART:
            value = -0.46
        elif prev in TIME_BOUNDARY | RELATIVE:
            value = -0.25
        elif prev in REPORTING | LEARNED_NEWS | {'截至目前'}:
            value = -0.32
    elif s == ',':
        if last in {'recently', 'lately'}:
            value = -0.29 - 0.15 * early
        elif last in ENGLISH_TIME:
            value = -0.12
        elif YEAR.search(tail):
            value = -0.055

    # The article or agent introduces the event after its time phrase.
    if word in {'the', 'a', 'an'}:
        definite = word == 'the'
        if last in {'after', 'following'}:
            value = -0.18 if definite else -0.05
        elif last in {'before', 'during', 'since'}:
            value = -0.09 if definite else -0.055
        elif last in ANNOUNCE:
            value = -0.27 if definite else -0.17
        elif last in {'recently', 'lately'}:
            value = -0.35 - 0.65 * early
        elif last in ENGLISH_TIME or YEAR.search(tail):
            value = -0.16 if definite else -0.06
        elif definite and last in {'by', 'between'}:
            value = -0.075 if last == 'by' else -0.12
    elif word in {'by', 'with'}:
        if last in ENGLISH_TIME or YEAR.search(tail):
            value = -0.11 if word == 'by' else 0.08
    elif word == 'on' and last == 'later':
        value = 0.22
    elif s == '的' and prev == '日':
        value = -0.3

    if s in MARKERS:
        value = MARKERS[s]
        if position == 0 and s in {'<|im_start|>', '<|im_end|>'}:
            value = 0.059 if s == '<|im_start|>' else 0.028
    return (doc, position, token, (tail + token)[-80:]), float(value)

"""A token-local detector of boundaries fused to words.

Document/tool starts and punctuation immediately joined to a letter receive
negative values. An isolated boundary does not. The response depends on the
boundary, the letter case, and whether the suffix is a common code type.
Common contractions and escapes are weaker than other quote/word fusions.
Chinese grammatical prefixes and Japanese particles fused to a word also
receive negative values. Ordinary words are near zero; no state or lookahead.
"""
READS = ()

MARKERS = {
    '<|endoftext|>': -1.69, '<|im_start|>': -0.96,
    '<|im_end|>': -0.15, '<tool_call>': -2.67,
    '<tool_response>': -2.10, '</tool_call>': -0.14,
    '</tool_response>': 0.12, '<think>': -0.22, '</think>': -0.34,
}
# Columns: lowercase letter, uppercase letter, lowercase word,
# uppercase word, capitalized/mixed-case word, common code type.
SHAPES = {
    '(': (-0.29, -0.50, -0.81, -0.96, -1.27, -0.68),
    '[': (-1.13, -1.82, -2.15, -2.33, -3.59, -1.86),
    '/': (-0.79, -1.14, -1.31, -1.70, -2.06, -1.47),
    ',': (-0.84, -1.04, -1.72, -1.60, -2.10, -1.49),
    '=': (-1.29, -1.56, -2.00, -1.45, -2.52, -1.48),
    '<': (-1.36, -1.96, -1.94, -2.23, -2.78, -2.05),
    '\t': (-0.78, -0.80, -0.97, -1.18, -1.27, -0.87),
    '.': (0.19, 0.00, 0.03, -0.20, -0.33, -0.01),
    '_': (0.04, -0.07, 0.04, 0.00, -0.64, 0.05),
    '-': (0.21, -0.13, -0.01, -0.38, -0.49, -0.01),
}
BOUNDARIES = {
    '*': -2.0, '>': -2.2, '+': -0.95, '@': -2.25, '&': -2.8,
    '"': -3.4, '“': -3.2, '#': -4.9, '$': -3.5, ':': -2.2,
    ')': -2.2, ']': -3.0, '—': -2.0, '…': -3.6, '?': -3.8,
    '\\': -2.1, ';': -2.2, '，': -0.65, '」': -1.4, '°': -0.7,
    '%': -3.2, '}': -2.3, '{': -1.6, '|': -2.6, '（': -2.6,
    '`': -1.6,
}
CODE_TYPES = set('''int str string bool boolean float double integer object
    list dict set map tuple char byte long short void'''.split())
C_PREPROCESSOR = set('include define if ifdef ifndef else elif endif pragma'.split())
CONTRACTIONS = {
    's': 0.11, 't': 0.00, 'm': -0.24, 're': -0.23,
    've': -0.63, 'll': -0.39, 'd': -0.93,
}
FRENCH_FUNCTIONS = set('est un une il elle on être était ai à'.split())
CHINESE_PREFIXES = {
    '是': -0.6, '在': -0.7, '为': -0.5,
    '对': -0.5, '有': -0.3, '了': -0.5, '让': -0.6,
    '给': -0.6,
}
# Japanese particle: response before kana text, before text containing kanji.
JAPANESE_PARTICLES = {
    'の': (-0.45, -1.05), 'を': (-0.90, -0.88), 'と': (-0.10, -0.74),
    'が': (-0.40, -1.00), 'に': (-0.20, -0.72),
}


def response(s):
    if s in MARKERS:
        return MARKERS[s]
    if len(s) < 2:
        return 0.0
    head, word = s[0], s[1:]
    if head in "'’":
        if word in CONTRACTIONS:
            return CONTRACTIONS[word]
        if word in FRENCH_FUNCTIONS:
            return -1.7
        if word.isalpha():
            return -2.65
    if head == '#' and word in C_PREPROCESSOR:
        return -1.1
    if head == '\\':
        if word == 'n':
            return -0.4
        if word == 't':
            return -0.67
        if word.startswith('x'):
            return -0.65
    if head == ';' and word == 's':  # apostrophe entity ending
        return -0.2
    if head == '(' and word in ('self', 'this', 'function', 'new'):
        return -0.45
    if head in '=,:' and word.lower() in ('true', 'false', 'none', 'null'):
        return -0.9
    if word[0].isalpha():
        if head in SHAPES:
            if word.lower() in CODE_TYPES:
                column = 5
            elif len(word) == 1:
                column = int(word.isupper())
            elif word.islower():
                column = 2
            elif word.isupper():
                column = 3
            else:
                column = 4
            return SHAPES[head][column]
        if head in BOUNDARIES:
            return BOUNDARIES[head]
    if head in '的和' or head in CHINESE_PREFIXES:
        if not all('\u4e00' <= c <= '\u9fff' for c in s):
            return 0.0
        if head == '的':
            return -1.4 if len(s) > 2 else -1.1
        if head == '和':
            return -2.1 if len(s) > 2 else -0.4
        return CHINESE_PREFIXES[head]
    # Japanese particles fused to a following word or word stem.
    if head in JAPANESE_PARTICLES and all(
        '\u3040' <= c <= '\u30ff' or '\u4e00' <= c <= '\u9fff' for c in s
    ):
        has_kanji = any('\u4e00' <= c <= '\u9fff' for c in word)
        return JAPANESE_PARTICLES[head][int(has_kanji)]
    return 0.0


def step(carry, prefix, upstream):
    return None, float(response(prefix.token_strings[-1]))

