"""A narrow lexical detector for the `return` word family.

In sampled high-importance contexts, `return` has a large positive
activation, and related tokens beginning with the same word also respond.
This simple rule predicts zero for everything else.
"""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
