programs.haiku:
"""Candidate 3: a past participle that completes a passive or copular construction.

Strength by context, set from the mean activation in each context:
- participle right after a be-verb ("is found", "can be used"): 1.2
- participle after a be-verb with adverbs between ("is not used", "is also known"): 0.6
- participle right after "not" or "also" with no be-verb ("does not include" aside): 0.9 / 0.3
- any other word right after "not": 0.2
Everything else is 0. Negative activations are small and ignored."""

READS = ()

BE = {"is", "was", "are", "were", "be", "been", "being", "am"}
ADVERBS = {"not", "also", "yet", "explicitly", "freely", "firstly", "only", "never", "still",
           "already", "then", "well", "often", "really", "n't", "t", "both", "all", "been",
           "rather", "indeed", "fully", "completely", "usually", "typically", "thus"}
IRREGULAR = {"given", "known", "shown", "made", "taken", "done", "written", "seen", "held",
             "found", "built", "sold", "chosen", "driven", "drawn", "thrown", "broken", "born",
             "kept", "left", "lost", "meant", "paid", "put", "read", "set", "sent", "spent",
             "told", "won", "brought", "caught", "bought", "taught", "thought", "shot", "cut",
             "hit", "let", "led", "fed", "struck", "met"}
PREDICATE_ADJ = {"available", "applicable", "limited", "present", "necessary", "possible",
                 "understood", "unchanged", "yet", "sure"}


def is_participle(word):
    return (len(word) > 3 and word.endswith("ed")) or word in IRREGULAR or word in PREDICATE_ADJ


def step(carry, prefix, upstream):
    words = [s.strip().lower() for s in prefix.token_strings]
    word = words[-1]
    prev = words[-2] if len(words) > 1 else ""
    value = 0.0
    if is_participle(word):
        for back in range(2, min(len(words), 5) + 1):
            if words[-back] in BE:
                value = 1.2
                break
            if words[-back] not in ADVERBS:
                break
        if value == 0.0:
            if prev == "not":
                value = 0.9
            elif prev == "also":
                value = 0.3
    elif prev == "not":
        value = 0.2
    return carry, value

programs.luna:
"""Approximate a participle cue: -ed (or a few irregular forms) after be/have."""

READS = ()

BACKGROUND = 0.004
PARTICIPLE_PULSE = 0.83
IRREGULAR_PARTICIPLES = {"given", "written", "drawn"}
AUXILIARIES = {
    "am", "are", "be", "been", "being", "is", "was", "were",
    "have", "has", "had",
}


def spelling(token):
    word = token.strip().lower()
    while word and not word[0].isalpha():
        word = word[1:]
    while word and not word[-1].isalpha():
        word = word[:-1]
    return word


def step(carry, prefix, upstream):
    word = spelling(prefix.token_strings[-1])
    is_participle = word.endswith("ed") or word in IRREGULAR_PARTICIPLES
    if not is_participle:
        return None, float(BACKGROUND)

    document = prefix.document_ids[-1]
    start = max(0, prefix.position - 4)
    for i in range(prefix.position - 1, start - 1, -1):
        if prefix.document_ids[i] != document:
            break
        if spelling(prefix.token_strings[i]) in AUXILIARIES:
            return None, float(PARTICIPLE_PULSE)
    return None, float(BACKGROUND)

