    'i': (0.42, 0.88),
    'you': (0.18, 1.04),
    'it': (0.0, 1.0),
    'we': (0.12, 0.85),
    'they': (-0.42, 0.9),
    'he': (-0.27, 0.85),
    'she': (-0.5, 0.83),
}
DEMONSTRATIVES = {'this', 'these', 'that', 'those'}
INDEFINITE = {
    'one', 'some', 'many', 'most', 'both', 'no', 'none', 'neither',
    'someone', 'everyone', 'everything', 'nothing', 'something', 'people',
}
FOREIGN_PRONOUNS = {
    'je', 'tu', 'il', 'elle', 'nous', 'vous', 'ils', 'elles',
    'ich', 'du', 'er', 'sie', 'wir', 'ihr',
    'я', 'ты', 'он', 'она', 'мы', 'вы', 'они', 'это',
    'se', 'você', 'eu', 'ele', 'ela', 'tôi', 'bạn',
}
CHINESE_PRONOUNS = {
    '我', '我们', '我們', '你', '你们', '您', '他', '她', '它',
    '他们', '他們', '这', '有人', '大家',
}


def context_score(token):
    if not token:
        return 0.35
    word = token.strip().lower()
    if '\n' in token:
        # Sentence punctuation survives a following line break.
        return -1.55 if any(c in token for c in '.?!。？！') else -0.65
    if word in {'was', 'were', 'be', 'been', 'am'}:
        return 1.55
    if word == 'is':
        return 0.65
    if word == 'making':
        return 0.0
    if word == 'sure':
        return -1.5
    if word in CUES:
        score = CUES[word]
        if score < -1.5 and token.strip()[0].isupper():
            score -= 0.2
        return score
    # Closing quotation marks do not hide the punctuation before them.
    punctuation = word.rstrip('\"\'”’')
    if punctuation and punctuation[-1] in ',;，；':
        return -1.9
    if punctuation and punctuation[-1] in '.?…。？！':
        return -2.05
    if word.endswith((':', '：')):
        return -1.3
    if word.endswith('!'):
        return -1.4
    if token.isspace():
        return -0.65
    if word in {'-', '--', '–', '—'}:
        return -1.25
    if word and word[-1] in ')]}':
        return -0.25
    if word and word[-1] in '([{"\'“‘':
        return -1.1
    if word.isdigit():
        return 0.2
    # Productive past-tense and participial endings usually precede objects.
    if word.endswith(('ed', 'ing')):
        return 1.0
    return 0.5 if token[0].isspace() else 0.3


def response(token, context, previous=''):
    text = token.strip()
    word = text.lower()
    capital = bool(text) and text[0].isupper()
    spaced = token.startswith(' ')
    negative, positive = min(context, 0.0), max(context, 0.0)
    if word in PERSONAL:
        if word == 'i' and text != 'I':
            return 0.0
        base, gain = PERSONAL[word]
        if previous.strip().lower() == 'do':
            # "Do it" is object-taking; "do they" is an inverted question.
            context = {'it': 1.25, 'i': 0.55, 'they': 0.15}.get(word, context)
            negative, positive = min(context, 0.0), max(context, 0.0)
        if word == 'i':
            if not spaced:
                base, gain = 0.04, 0.75
            return base + gain * negative + 0.83 * positive
        if not spaced and not capital:
            # Usually a subword, not a free-standing subject pronoun.
            return {'we': 0.5, 'he': 0.3, 'she': -0.8}.get(word, 0.0)
        if capital:
            base -= 0.7
            gain *= 0.8
            if not spaced:
                base += 0.4
                gain += 0.1
        return base + gain * negative + 0.95 * positive
    if word == 'there':
        if capital:
            return -0.24 + 0.57 * negative + 0.88 * positive
        return 0.68 + 0.87 * context
    if word in DEMONSTRATIVES:
        if word == 'that':
            return (-0.18 if capital else -0.03) + 0.12 * negative
        if word == 'those':
            return -0.08 + 0.2 * negative
        if capital:
            return -0.55 + 0.23 * negative + 0.12 * positive
        return -0.16 + 0.42 * negative + 0.14 * positive
    if word in INDEFINITE:
        base = -0.2
        if word in {'everyone', 'someone', 'everything'}:
            base = -0.4
        if word in {'many', 'most', 'both', 'no', 'none', 'neither', 'nothing'}:
            base = 0.0
        if capital:
            base -= 0.25
        gain = 0.65 if word in {'one', 'someone', 'nothing'} else 0.4
        return base + gain * negative + 0.14 * positive
    if word in FOREIGN_PRONOUNS:
        if not spaced and not capital:
            return 0.0
        return (-0.65 if capital else -0.2) + 0.5 * negative + 0.2 * positive
    if token in CHINESE_PRONOUNS:
        return -0.2 + 0.55 * negative + 0.5 * positive
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    value = response(token, context_score(previous), previous)
    return (doc, token), float(value)

