"""Predict the negative pulse on a personal pronoun opening a clause.

A pronoun after a comma, sentence mark, or subordinating/conjoining word
gets a negative value; other tokens are left near zero. Clause-opening
"this/these/there/one" get a smaller version of the same pulse.
"""
READS = ()

SUBJECT_PRONOUNS = frozenset({
    "i", "we", "you", "he", "she", "it", "they", "ich", "nous",
})
CLAUSE_WORDS = frozenset({
    "if", "when", "where", "while", "because", "but", "and", "or",
    "so", "though", "although", "since", "as", "then", "however",
    "after", "before", "once", "unless", "until", "which", "who",
    "that",
})
CLAUSE_OPENERS = frozenset({"this", "these", "there", "one"})
BOUNDARIES = ".,?!:;—–…"


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip()
    word = token.casefold()
    if not word:
        return None, 0.0

    previous = ""
    if len(prefix.token_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        previous = prefix.token_strings[-2]
    previous_word = previous.strip().casefold()
    punctuation_edge = (
        "\n" in previous
        or previous.rstrip().endswith(tuple(BOUNDARIES))
    )
    conjunction_edge = previous_word in CLAUSE_WORDS

    if word in SUBJECT_PRONOUNS:
        if conjunction_edge:
            return None, -1.9
        if punctuation_edge:
            return None, -1.65
    if word in CLAUSE_OPENERS and (conjunction_edge or punctuation_edge):
        return None, -1.1
    return None, 0.0

programs.sol:
"""An initial-R detector, with spelling and word-boundary adjustments.

R at a word or identifier start usually has a negative activation. Re- is
weaker than other R spellings; capitals are stronger. A fragment inside a
word is weaker, except that a lowercase-to-uppercase transition can start a
new word in an identifier. The closing tool-call marker is a separate cue.
The numerical strengths are fitted approximations, not exact token values.
"""
import unicodedata

READS = ()
R_LETTERS = frozenset('rрرรᚱ')  # Latin, Cyrillic, Arabic, Thai, Runic R.


def response(token, previous):
    if token == '</tool_call>':
        return -1.70
    word = token.lstrip(' \t\r\n._([/\\-:\'"`{<>+=#$%@!*?,;')
    if not word or word[0].lower() not in R_LETTERS:
        return -0.002
    if token.startswith(("'re", '’re')):  # English contraction, not a new word.
        return -0.002

    lower = word.lower()
    n = len(word)
    capital = word[0].isupper()
    second = unicodedata.normalize('NFD', lower[1:2])[:1]
    re_prefix = lower[0] == 'r' and second == 'e'
    value = -1.68
    if re_prefix:
        value += 0.70
    else:
        value += 0.06 * (min(n, 10) - 5)
        if second in 'aio' and second:
            value += 0.13
        elif second == 'u':
            value -= 0.12
    if lower[0] != 'r':
        value += 0.18
    if capital:
        value -= 0.34
    if not re_prefix and word[1:2].isupper():
        value -= 0.13
    if n == 1:
        value += 0.46
    elif n == 2:
        value += 0.18
    if lower.endswith('s') and n > 3:
        value += 0.07
    if lower == 'right':
        value += 0.79
    elif lower in ('really', 'rather', 'round'):
        value += 0.40

    if token == word:
        value += 0.20
        inside_word = previous[-1:].isalpha() and (
            not capital or previous[-1:].isupper())
        if inside_word:
            value += 1.13 - 0.53 * re_prefix + 0.24 * capital
    elif token[0].isspace():
        value += 0.15
    else:
        value -= 0.10
    return min(0.08, value)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1]
    return (document, token), float(response(token, previous))

