"""Auxiliary contractions, plus weaker spelling responses around the letter V.

Contracted HAVE ('ve) is the strongest positive cue. ARE, WILL, HAD/WOULD and AM
contractions are weaker, and the immediately preceding pronoun adjusts them.
Short V-containing fragments turn negative with recent Czech/Slovak,
Nordic or Hungarian spelling cues. Short Cyrillic vowel-plus-в fragments
are also negative. Chinese 有 ('have') gets a positive response; compounds
are weaker. Other tokens are approximated by zero. This models spelling
associations, not the meaning of HAVE in arbitrary sentences.
"""
READS = ()
SLAVIC_LETTERS = frozenset('čďěľĺňřšťůžČĎĚĽĹŇŘŠŤŮŽ')
NORDIC_OR_HUNGARIAN = frozenset('åøæőűÅØÆŐŰ')
CONTRACTIONS = {"'ve": 3.0, "'re": 0.79, "'ll": 0.70,
                "'d": 0.49, "'m": 0.285}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    recent, previous = ('', '') if start else carry[1:]
    raw = prefix.token_strings[-1]
    text = raw.strip()
    suffix = text.replace('’', "'")
    subject = previous.strip(' \t\n\"“”()').lower()
    value = 0.0
    if suffix in CONTRACTIONS:
        value = CONTRACTIONS[suffix]
        if suffix == "'ve":
            value += {'we': 0.54, 'they': 0.29, 'you': 0.13}.get(subject, 0.0)
            if subject in {'would', 'could', 'should', 'might', 'must'}:
                value -= 0.35
            if '’' in text:
                value -= 0.12
            if start:
                value = 1.55
        elif suffix in {"'re", "'ll", "'d"}:
            if subject == 'we':
                value += 0.21 if suffix != "'d" else 0.16
            elif subject == 'they':
                value += 0.17 if suffix == "'re" else 0.10
            elif subject == 'you' and suffix == "'ll":
                value -= 0.05
    elif '有' in text:
        if text == '有':
            value = 0.70
        elif '没有' in text or '沒有' in text:
            value = -0.08
        elif '所有' not in text:
            value = 0.30 if text.startswith('有') else 0.20
            if (text.endswith('有')
                    and text[:-1] in '也都更会很中上才又是仍总'):
                value = 0.53
    elif 'v' in text.lower() and text.isalpha() and len(text) <= 4:
        slavic = any(c in SLAVIC_LETTERS for c in recent + text)
        northern = any(c in NORDIC_OR_HUNGARIAN for c in recent + text)
        accented = any('\u00c0' <= c <= '\u024f' for c in recent[-100:] + text)
        if slavic:
            value = -1.34 if text == 'v' else -1.20 if text == 've' else -0.72
        elif northern:
            value = -1.10 if text == 'v' else -0.70 if text == 've' else -0.58
        elif text in {'v', 'V'}:
            if start:
                value = -1.33 if text == 'v' else -0.71
            elif text == 'V':
                value = 0.21 if raw[:1].isspace() else 0.36
            else:
                value = -0.10 if accented else 0.10
        elif text == 've':
            value = 0.0 if accented else 0.34
            if subject in {'i', 'you', 'we', 'they'}:
                value = 1.5
        elif accented and not text.isupper():
            value = -0.06
        elif text in {'IV', 'VI', 'VA', 'VE', 'VO', 'UV', 'OV'}:
            value = 0.40
        elif text in {'ive', 'ives'}:
            value = 0.22
    elif len(text) <= 3 and ('ив' in text or 'ев' in text or 'ав' in text):
        value = -0.40
    elif text == 'вер':
        value = -0.70
    return (doc, (recent + raw)[-150:], raw), float(value)

