The main positive signal is a property or process after a concrete referent:
'cell count', 'file size', 'water level', or 'text-align'. Word classes cover
related compounds, with stronger responses for a few common relationships.
The program also gives fixed offsets to conversation markers, contractions,
and discourse linkers. It omits most small, idiosyncratic lexical variation.
"""
import re
READS = ()

BIOLOGY = set('''cell protein dna rna mrna gene serum plasma glucose
cholesterol sugar hormone antigen tissue muscle brain chromosomal cromosomal'''.split())
FLUIDS = set('''water groundwater air gas liquid fluid oil blood vapor
coolant soil'''.split())
LANGUAGE = set('word sentence character letter'.split())
MEDIA = set('image picture video audio speech sound model data sample'.split())
OBJECTS = set('''line body object asset motor vehicle battery electrode plant
heart particle atom electron ion node rod row column table block tree root
module system container pixel font screen canvas window string byte bit code
document product material library room frame processor kernel chord fiber
disk user cabinet ground wave vessel card thread packet'''.split())
ENTITIES = BIOLOGY | FLUIDS | LANGUAGE | MEDIA | OBJECTS | {'file', 'text'}

DIMENSIONS = set('size sizes height width length depth weight mass volume'.split())
PHYSICAL = set('''temperature temperatures pressure density concentration
abundance intensity'''.split())
METADATA = set('''location path info information reference references list
index format extension extensions checksum visibility notfounderror mode entry'''.split())
LAYOUT = {'align', 'alignment', 'spacing', 'indent'}
PROCESSES = set('''preparation survival death damage transfer integration
placement position protection completion detection selection expression fit'''.split())
OTHER = set('''surface structure shape cycle division growth activity function
response production culture content contents type types storage retrieval
processing analysis recognition management access distribution loss usage
proliferation viability differentiation infiltration migration'''.split())

MARKERS = {
    '<tool_response>': .076, '</tool_response>': .047,
    '<tool_call>': -.029, '</tool_call>': -.052,
    '<think>': -.036, '</think>': .052,
    '<|endoftext|>': .030, '<|im_start|>': -.008, '<|im_end|>': .018,
}
LINKERS = {'however': -.095, 'moreover': -.10, 'furthermore': -.06,
           'nevertheless': -.04, 'nonetheless': -.03}


def last_word(s):
    s = re.sub(r'([a-z])([A-Z])', r'\1 \2', s)
