    if head in {'level', 'levels'}:
        value = .025 if head == 'level' else -.09
        if entity:
            value = .50 if head == 'level' else .28
        if prev == 'protein':
            value = .77 if head == 'level' else .53
    elif head in {'count', 'number', 'numbers'} and entity:
        value = .38 if head == 'count' else .25
        if head == 'count' and prev in LANGUAGE | {'cell', 'card'}:
            value = .78
        elif head == 'count' and prev in {'blood', 'thread', 'packet'}:
            value = .60
    elif head in DIMENSIONS and entity:
        value = .25
        if head == 'size' and prev in {'file', 'cell'}:
            value = .58
        elif head == 'weight' and prev in {'sample', 'font'}:
            value = .48
        elif head == 'height' and prev == 'line':
            value = .65
    elif head in PHYSICAL and entity:
        value = .34
    elif head in {'speed', 'velocity', 'quality'} and entity:
        value = .38
    elif head in METADATA and entity:
        value = .30 if prev in {'file', 'cell', 'object'} else .09
        if prev == 'file' and head in {'visibility', 'checksum', 'notfounderror'}:
            value = .75
    elif head in LAYOUT:
        if prev == 'text':
            value = .67
        elif prev in LANGUAGE:
            value = .35
    elif head in PROCESSES and entity:
        value = .28
        if prev == 'cell' and head in {'death', 'survival'}:
            value = .55
        elif prev == 'dna' and head in {'damage', 'integration'}:
            value = .55
        elif prev == 'sample' and head == 'preparation':
            value = .78
        elif prev == 'file' and head == 'transfer':
            value = .48
