READS = ()

# Completed word families and suffixes with a weaker cl response.
WEAK_WORDS = (
    'class', 'clear', 'click', 'cloth', 'clever', 'clock', 'clerk',
    'clusio', 'clero', 'closely',
)
MODERATE_WORDS = ('client', 'cloud', 'close', 'clean', 'clinic', 'climb')


def response(text):
    word = text.strip().lstrip('_./-(:\"\'')
    lower = word.lower()
    space = text[:1].isspace()
    if 'cl' not in lower:
        if lower == '클':
            return -4.45
        if lower.startswith(('クラ', 'クリ', 'クル', 'クレ', 'クロ')):
            return -1.44
        if 'кл' in lower:
            return -2.0 if lower in ('кл', 'кли') else -0.7
        if lower.startswith(('chlorine', 'chloride')):
            return -2.0
        if lower.startswith(('kl', 'chl')):
            return -0.8
        return -0.001

    before, after = lower.split('cl', 1)
    if not after:
        if len(before) > 3:
            return -0.001
        if before == 'y':
            return -6.16
        if before.endswith('de'):
            return -2.25
        if before:
            return -3.2
        if word.isupper():
            return -5.7 if space else -6.4
        if word[0].isupper():
            return -4.44
        return -4.53 if space else -5.77

    if before:
        if before.endswith('de'):
            return -1.25
        if before.endswith(('en', 'in')) and after.startswith(('os', 'us')):
            return -1.13
        if before.endswith('cy'):
            return -0.38
        return -0.12

    if len(after) == 1:
        if after == 'i':
            if text.startswith('-'):
                return -3.85
            return -1.75 if text.startswith('/') else -2.57
        if after in 'aeou':
            return -1.8
        return -3.2
    if lower.startswith(('closer', 'closur')):
        return -1.58
    if lower.startswith(WEAK_WORDS):
        return -0.36
    if lower.startswith(MODERATE_WORDS):
        return -0.92
    if lower.startswith('claim'):
        return -1.6
    if len(after) <= 4:
        return -2.25
    if len(after) <= 6:
        return -1.5
    return -0.8


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    value = response(text)
    continues = text[:1].isascii() and text[:1].isalpha()
    if carry is not None and carry[0] == doc and carry[1] and continues:
        if 'cl' not in text.lower():
            value -= 0.45
    return (doc, text.lower().endswith('cl')), float(value)

