programs.haiku:
"""layers.0.mlp.down_proj:4529 -- a "to" detector that depends on what the "to" does.

The component is large on the word "to" (and on "into") when "to" marks a prepositional
target: "attention to", "access to", "with regard to", "given to", "added to", "referred to",
"into the room". It is near zero or negative when "to" starts an infinitive ("need to",
"ready to", "way to", "how to") or is a comparison/relation ("similar to", "due to").

The program reads only the current token and the token before it, in the same document:
  * "into", "onto", "towards" -> a clear positive value;
  * "to" after a word of giving, attaching, referring, responding or paying attention
    (attention, access, regard, respect, given, added, referred, responds, ...) -> high;
  * "to" after a word that takes an infinitive (need, want, able, ready, decided, way,
    order, how, ...) -> slightly negative;
  * "to" after a comparison or relation word (similar, equal, close, due, related, ...) -> 0;
  * any other "to" -> a modest positive value;
  * every other token -> 0.
"""

READS = ()

INTO_WORDS = {"into", "Into", " into", " Into"}
TOWARD_WORDS = {" onto", " towards", " toward", " Towards", " Toward", " upon"}
TO_WORDS = {" to", "to", " To", "To", " TO", "-to"}

# words after which "to" starts an infinitive: "decided to", "ready to", "way to"
INFINITIVE_WORDS = set(
    """need needs needed want wants wanted wanting going trying tried try tries able unable
    ready decided decides decide possible impossible likely unlikely ability attempt attempts
    failed continued continue began begin choose chose designed forced desire opportunity hard
    difficult easy necessary went go used plans seeks tends allowed agreed agree chance
    eager willing way order how required have has had""".split()
)

# words of giving, attaching, referring, responding, attention: "given to", "attention to"
PREPOSITIONAL_WORDS = set(
    """attention regard regards respect respects reference access given gives give responds
    respond response responses answer answers contribution addition exposure pay paid applied
    applies apply sure added attached assigned referred offered provided presented shown sent
    subscribe appeal made said as only""".split()
)

# comparison and relation words, where "to" is about zero: "similar to", "due to"
ZERO_WORDS = set(
    """similar equal equivalent close closer parallel proportional adjacent prior due subject
    related according relevant leading lead leads up""".split()
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip()
    if token in INTO_WORDS:
        value = 0.85
    elif token in TOWARD_WORDS:
        value = 0.5
    elif token in TO_WORDS:
        if prev in INFINITIVE_WORDS:
            value = -0.25
        elif prev in PREPOSITIONAL_WORDS:
            value = 1.2
        elif prev in ZERO_WORDS:
            value = 0.0
        else:
            value = 0.35
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""A calibrated, sparse cue on the common prepositions seen in examples."""
READS = ()


def step(carry, prefix, upstream):
    """Predict modest activation on 'to', 'into', and 'for' tokens."""
    token = prefix.token_strings[-1]
    if token == " to":
        return None, 0.27
    if token == " into":
        return None, 0.39
    if token == " for":
        return None, 0.17
    return None, 0.0

programs.haiku:
"""Component layers.0.mlp.down_proj:4530 -- the English preposition "in".

What it does: this component writes a positive "this is 'in'" signal into the
residual stream. It is strongest on the word " in" (about 0.3 on average, up to
about 1.0), and weaker on the same-meaning or same-role words of other languages
(French/Italian/Spanish/German-style "la", "en", "des", "di", "les", "el").

Modulation on " in", by the word just before it:
  - after a form of "to be" (is, are, was, be...), or after "the" or a number:
    stronger (about 0.6);
  - after a comma: weaker (about 0.27);
  - after a past participle ending in -ed (resulted in, interested in): weakest (about 0.16);
  - otherwise about 0.33.

At the first token of a document (no context), the activation is set by the
word alone: "the"/"The" about 0.7, " in" about 1.0, " and" 0.45, " of" 0.37,
" to" 0.33, " a" 0.29. Every other token predicts 0.
"""
READS = ()

COPULA = {" is", " are", " was", " were", " be", " been", " being", " am"}
DOC_START = {" the": 0.68, "The": 0.69, " in": 0.98, " and": 0.45, " of": 0.37, " to": 0.33, " a": 0.29}
OTHER_IN = {" la": 0.18, " en": 0.13, " des": 0.11, " di": 0.09, " les": 0.09, " el": 0.09}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1]
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return None, DOC_START.get(word, 0.0)
    if word != " in":
        return None, OTHER_IN.get(word, 0.0)
    before = prefix.token_strings[-2]
    if before in COPULA or before == " the" or before.strip().isdigit():
        return None, 0.6
    if before == ",":
        return None, 0.27
    if before.strip().endswith("ed"):
        return None, 0.16
    return None, 0.33

programs.sol:
"""Detect effect/affect vocabulary, rather than causation in general.

Effect/effects have the largest response, then affect and impact. Efficacy,
influence and benefits respond less. Small named word classes cover change,
feelings, relationships, importance and harm, with a few translations and
word pieces. A preceding response spills onto of/on/by; state resets between
documents. There is also a small response to the tool-response marker.
Other tokens get zero: weaker, idiosyncratic lexical responses are omitted.
"""

READS = ()

ASSISTANCE = {
    'help', 'helps', 'helped', 'helping', 'helpful', 'useful',
    'advantage', 'advantages', 'advantageous', 'contribution', 'contributions',
}
CHANGE = {'change', 'changes', 'changed', 'changing', 'unchanged'}
FEELINGS = {
    'feel', 'feels', 'felt', 'touch', 'contact', 'emotional',
    'emotion', 'emotions', 'amazed', 'affection', 'touching', 'touched',
    'compassionate', 'thoughtful', 'mindful', 'profound',
}
RELATIONS = {
    'relationship', 'relationships', 'aspect', 'aspects',
    'interaction', 'interactions', 'interact', 'behavior', 'behaviour',
    'dynamic', 'dynamics', 'dependent',
    'interfere', 'interfering', 'interference', 'controlled',
}
IMPORTANCE = {
    'important', 'significant', 'significantly', 'relevant', 'critical',
    'crucial', 'vital', 'powerful', 'successful', 'lasting', 'pronounced',
}
EFFECT_ASSESSMENT = {'consequences', 'meaningful', 'efficacy'}


def lexical_value(raw):
    word = raw.strip().strip('-_.,:;!?()[]{}"\'')
    w = word.lower()
    if w in {'effect', 'effects'}:
        return 5.0
    if w in {'ffect', 'ffects'}:  # effect/affect split into word pieces
        return 4.3
    if w == 'affect':
        return 4.65
    if w in {'affects', 'affecting', 'unaffected'}:
        return 4.3
    if w == 'affected':
        return 3.9
    if w == 'effected':
        return 2.9
    if w in {'impact', 'impacts', 'impactful'}:
        return 3.8 if word == 'impact' and raw.startswith(' ') else 3.5
    if w in {'impacted', 'impacting'}:
        return 3.1
    if w in {'effective', 'ffective'}:
        return 2.75 if word.islower() else 2.35
    if w in {'effectively', 'effectiveness', 'ineffective'}:
        return 2.15
    if w in {'influence', 'influences', 'influenced', 'influencing'}:
        return 1.25
    if w == 'influential':
        return 1.65
    if w in {'benefit', 'benefits', 'beneficial', 'benefited'}:
        return 1.45
    if w == 'benef':
        return 0.85
    if w in {'role', 'feeling', 'feelings'} | EFFECT_ASSESSMENT:
        return 1.1
    if w in {'importance', 'significance', 'roles'}:
        return 0.85
    if w in {'implications', 'repercussions'}:
        return 1.5
    if w in ASSISTANCE | CHANGE | FEELINGS | RELATIONS:
        return 0.7
    if w in IMPORTANCE:
        return 0.55
    if w in {
        'response', 'responses', 'respond', 'responds', 'treatment', 'treatments',
        'treated', 'successfully', 'damage', 'damages', 'damaged', 'harm',
        'contribute', 'contributes', 'contributed', 'contributing',
        'essential', 'presence', 'impression', 'impressed',
    }:
        return 0.4
    if w in {'symptom', 'symptoms', 'severity', 'painful', 'harmful'}:
        return 0.75
    if w in {'ful', 'eful'}:  # adjective suffix expressing a quality
        return 0.75
    if w.endswith('ful') and w.isalpha():
        return 0.3
    if word == '影响力':
        return 2.25
    if '影响' in word:
        return 3.2
    if '影響' in word:
        return 2.3
    if '效应' in word or '效應' in word:
        return 3.9
    if '效果' in word or '효과' in word:
        return 3.0
    if '作用' in word:
        return 2.1
    if '成效' in word or '有效' in word:
        return 1.75
    if '生效' in word:
        return 2.7
    if word in {'感受', '感受到', '好处', '危害'}:
        return 1.3
    if word in {'效', '响'}:
        return 1.2
    if word in {'伤', '痛', '享受'}:
        return 0.8
    if word in {'影', '化', '動', '动', '利'}:
        return 0.5
    if word in {'感觉', '感覺', '感じ', '感情', '感', '受', '受到'}:
        return 0.85
    if word in {'改变', '变化', '變', '变', '変', '帮助', '有助于'}:
        return 0.7
    # Romance and Russian word stems for effects and influence.
    if w == 'afect':
        return 2.7
    if w == 'efect':
        return 1.8
    if w == 'effet':
        return 1.35
    if w == 'эфф':
        return 2.45
    if w == 'эффектив':
        return 1.3
    if w in {'вли', 'роль'}:
        return 1.1
    if w == 'влия':
        return 2.2
    if w == 'воздейств':
        return 2.8
    if raw == '<tool_response>':
        return 0.73
    return 0.0


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == document else 0.0
    strength = lexical_value(raw)
    value = strength
    # The effect phrase continues onto a following connecting preposition.
    connector = raw.strip().lower()
    if connector in {'of', 'on'}:
        value += 0.28 * previous
    elif connector == 'by':
        value += 0.18 * previous
    return (document, strength), value

