    elif "有效" in word:
        value = 1.8
    elif "作用" in word:
        value = 2.15
    elif "influenc" in word:
        value = 1.2
    elif "benefit" in word:
        value = 1.4
    elif "feel" in word:
        value = 0.85
    elif "role" in word:
        value = 1.0
    elif "help" in word or "change" in word:
        value = 0.7
    elif "relationship" in word:
        value = 0.7
    elif "significant" in word:
        value = 0.6
    elif "important" in word:
        value = 0.45
    elif "contact" in word or "touch" in word:
        value = 0.6
    elif "aspect" in word:
        value = 0.7
    elif "advantage" in word or "useful" in word:
        value = 0.6
