programs.sol:
"""A detector for the vocabulary and page furniture of coursework.

The strongest negative cue is homework. Teaching roles, lectures, scientific
subjects, and textbook labels contribute less. Recognize split spellings and
strengthen book/solution labels when course terminology repeats nearby.
Ordinal-number editions are recognized as book metadata. Also recognize the
'View Full Document'/'This preview' furniture of study sites and the opening
acknowledgement of a reasoning response. Most other tokens predict zero.
"""
import re

READS = ()
TEACHING = {'instructor', 'instructors', 'tutor', 'tutors'}
STUDY_MATERIAL = {'lecture', 'lectures', 'workbook', 'workbooks', 'semester'}
LIFE_SCIENCES = {'biology', 'physiology', 'anatomy', 'genetics', 'ecology'}
BOOK_LABELS = {'textbook', 'chapter', 'chapters', 'edition', 'principles',
               'fundamentals', 'notes', 'guides', 'exam', 'quiz'}
SOLUTIONS = {'solution', 'solutions', 'exercise', 'exercises', 'practice'}
STUDY_SITES = {'brainmass', 'transtutors', 'webassign'}
WORDS = (TEACHING | STUDY_MATERIAL | LIFE_SCIENCES | BOOK_LABELS | SOLUTIONS
         | STUDY_SITES
         | {'homework', 'worksheet', 'intro', 'introduction', 'introductory'})
COURSE = re.compile(
    r'homework|textbook|worksheet|lecture|semester|physics|chemistry|biology|'
    r'math|algebra|calculus|economics|exam|course|instructor|assignment', re.I)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lower()
    title = raw[:1].isupper()
    split = False
    if raw.isalpha() and not token[:1].isspace():
        tail = re.search(r'[A-Za-z]+$', recent)
        if tail and (tail[0] + raw).lower() in WORDS:
            word = (tail[0] + raw).lower()
            split = True
        elif tail and (tail[0] + raw).lower().endswith('homework'):
            word, split = 'homework', True
    if split:
        title = (tail[0] + raw)[-len(word)].isupper()
    course_strength = min(3, len(COURSE.findall(recent)))
    value = 0.0
    if word == 'homework':
        value = -0.35 - 0.18 * title - 0.10 * course_strength - 0.08 * split
    elif word == 'hw' and raw.isupper():
        value = -0.30
    elif word in TEACHING:
        value = -0.22
    elif word in STUDY_MATERIAL:
        value = -0.13 - 0.07 * title
    elif word in LIFE_SCIENCES:
        value = -0.13
    elif word == 'worksheet':
        value = -0.08 if token[:1].isspace() else -0.22
    elif word == 'edition' and re.search(
            r'(?:\d+(?:st|nd|rd|th)|first|second|third|fourth|fifth|sixth|'
            r'seventh|eighth|ninth|tenth)\s*$', recent, re.I):
        value = -0.25 - 0.07 * title
    elif word in {'notes', 'guides'} and re.search(
            r'textbook|lecture|study', recent, re.I):
        value = -0.20 - 0.08 * title
    elif word in BOOK_LABELS:
        value = -0.04 - 0.09 * title - 0.09 * course_strength
    elif word in SOLUTIONS:
        value = -0.02 - 0.07 * title - 0.13 * course_strength - 0.08 * split
    elif word in {'intro', 'introduction', 'introductory'}:
        value = -0.02 - 0.10 * title - 0.07 * course_strength
    elif word in STUDY_SITES:
        value = -0.22
    elif word == 'document' and recent.lower().endswith('view full'):
        value = -0.16
    elif word == 'preview' and recent.endswith('This'):
        value = -0.07
    elif word in {'okay', 'alright', 'ok'}:
        value = -0.05 - 0.03 * title
        if '<think>' in recent:
            value -= 0.11
    elif raw == '#####':
        value = -0.04 if token[:1].isspace() else -0.17
    return (doc, (recent + token)[-120:]), float(value)

programs.haiku:
"""Layer-0 MLP down_proj component 4532 (explain program, lexical version).

The component is a weak, token-level feature. Its activation is clearly negative on the
word "Homework" (typically the course-document headers "Homework Statement", "Homework
Help", "Homework Equations"), and mildly negative on other course-material words such as
worksheet, textbook, edition, chapter, lecture, instructor, exam, practice, exercises, lab,
notes and solutions. Elsewhere it is close to zero, with no clear sign.

The program predicts those values from the newest token alone and is 0 otherwise.
"""

READS = ()

HOMEWORK = {"homework"}
COURSE_MATERIAL = {
    "worksheet", "worksheets", "textbook", "edition", "chapter", "lecture",
    "instructor", "exam", "practice", "exercises", "lab", "notes", "solutions", "tutors",
}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in HOMEWORK:
        value = -0.5
    elif word in COURSE_MATERIAL:
        value = -0.1
    else:
        value = 0.0
    return None, value

programs.luna:
"""A small negative cue for indefinite and alternative words.

The component is most visibly active on words such as every, either,
whatever, and however. This approximates that broad grammatical family;
it does not try to model the component's many context-dependent exceptions.
"""
READS = ()

UNIVERSAL_OR_INDEFINITE = {
    "every", "everyone", "everybody", "everything", "everywhere",
    "any", "anyone", "anybody", "anything", "anywhere",
    "whatever", "whoever", "whichever", "wherever", "whenever",
    "either", "neither", "nothing", "nobody", "none", "noone",
    "somewhere", "someone", "something", "one",
}

CONTRAST_OR_CHOICE = {
    "however", "nevertheless", "despite", "alternatively",
}

# A few clear equivalents seen in other writing systems in the harvested
# examples: any (Chinese/Spanish), all (Arabic), and Japanese wh-determiner.
OTHER_LANGUAGE_INDEFINITES = {"任何", "cualquier", "كل", "ど"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if word in UNIVERSAL_OR_INDEFINITE:
        return None, -0.5
    if word in CONTRAST_OR_CHOICE:
        return None, -0.4
    if word in OTHER_LANGUAGE_INDEFINITES:
        return None, -0.4
    return None, 0.0

programs.sol:
"""A spelling-based approximation to a negative wrap-up/aggregation signal.

The strongest cues are conclusion headings, 'in conclusion', summaries,
and 'overall'. Inference connectives and completion expressions are weaker.
Recognize several translated counterparts and split word spellings. Keep
only a short text suffix, reset between documents, and predict zero elsewhere.
"""
import re

READS = ()
INFERENCE = {
    'therefore': (-0.16, -0.54, -1.05),
    'thus': (-0.19, -0.38, -0.74),
    'hence': (-0.18, -0.30, -1.25),
}
CONCLUSIONS = {'conclusion', 'conclusions', 'conclusión', 'conclusiones'}
COMPLETE_CUES = {'up', 'of', 'line', 'final', 'thoughts', 'answer'}
CLOSING_WORDS = {
    'finally', 'lastly', 'ultimately', 'closing', 'findings', 'outlook',
    'discussion', 'references', 'remember', 'hope', 'hopes', 'goodbye',
}


def response(token, recent):
    raw = token.strip()
    if not raw:
        return 0.0
    if raw == '</think>':
        return -1.16
    suffix = re.search(r'[^\W\d_]+$', recent + token)
    word = suffix.group() if suffix else raw
    if raw.lower() in COMPLETE_CUES | INFERENCE.keys():
        word = raw
    if raw.lower().startswith(('concl', 'summar', 'overall')):
        word = raw
    w = word.lower()
    before = (recent + token)[:-len(word)].rstrip()
    last = re.search(r'([^\W\d_]+)$', before)
    previous = last.group().lower() if last else ''
    title = word[0].isupper()
    spaced = token.startswith(' ')
    markdown = before.endswith(('#', '*'))

    if w in CONCLUSIONS:
        if previous == 'in':
            return -10.6
        if word.isupper():
            return -7.1 if raw == 'IONS' else -10.7
        if title:
            return -10.3 if w.endswith('s') or markdown else -7.8
        return -3.7 if w.endswith('s') else -5.3
    if w.startswith('conclud'):
        if title or previous == 'to':
            return -6.5 if title else -4.6
        return -2.7 if w.endswith('ed') else -2.9 if w.endswith('es') else -3.4
    if w.startswith('conclus') or w == 'concl':
        return -8.2 if word.isupper() else -2.8
    if w.startswith('summar'):
        if previous in {'in', 'to'}:
            return -7.45 if previous == 'in' else -4.8
        if w == 'summary':
            if word.isupper():
                return -2.7
            if title:
                return -6.1 if markdown else -4.0
            return -2.56 if spaced else -1.8
        return -1.6
    if w == 'summation':
        return -3.0
    if w == 'overall':
        return -4.0 if title and not spaced else -3.3
    if w in INFERENCE:
        ordinary, capitalized, initial = INFERENCE[w]
        return (capitalized if title else ordinary) if spaced else initial
    if raw == ',' and previous in INFERENCE:
        return -0.34
    if w == 'final':
        return -1.0 if title else -0.3
    if previous == 'final' and w in {'thoughts', 'answer'}:
        return -3.5 if w == 'thoughts' else -2.0
    if w == 'up':
        if re.search(r'\bwrap(?:s|ped|ping)?(?:\s+\w+)?[- ]*$', before, re.I):
            return -5.0
        if previous in {'sum', 'summing', 'summed'}:
            return -3.0
        if previous in {'end', 'ends', 'ended', 'ending'}:
            return -1.9
        return -0.16
    if w == 'line' and previous == 'bottom':
        return -2.5
    if w == 'of' and previous in CONCLUSIONS | {'summary', 'overall'}:
        return -0.9
    if w == 'boxed':
        return -0.8 if spaced else -2.0
    if w in CLOSING_WORDS:
        return -0.5

    # Chinese/Japanese: summing up, conclusion, overall, and finally.
    if raw in {'总之', '總之', '总而言之', '总的来说', '综上所述'}:
        return -5.6
    if raw in {'上', '所述'} and recent.endswith(('综', '综上', '綜', '綜上')):
        return -5.6
    if raw in {'结', '結'}:
        return -5.6 if recent.endswith(('总', '總')) else -3.4
    if raw in {'论', '論'} and recent.endswith(('结', '結')):
        return -5.7
    if raw in {'总结', '總結', '综', '综上', '結論', '结论'}:
        return -4.9
    if raw == 'まとめ':
        return -2.6
    if raw in {'以上', '總'}:
        return -1.6
    if raw in {'整体', '综合', '全文', '綜合', '总体', '最后', '最後', '最终'}:
        return -1.0
    # Russian conclusion/deduction stems and 'thus'.
    if w.startswith('заключ'):
        return -5.2 if w == 'заключ' else -2.2
    if w == 'зак':
        return -0.9
    if w.startswith('вывод'):
        return -2.5 if w == 'вывод' else -1.4
    if w == 'образом' and previous == 'таким':
        return -2.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    return (doc, (recent + token)[-100:]), float(response(token, recent))

programs.haiku:
"""Draft 4: wrap-up detector with context: a conclusion/summary word is strongest right after 'In'
(as in 'In conclusion', 'In summary') or at the start of a sentence; closing words are weaker; and
'up' after sum/wrap/end verbs (as in 'sum up', 'wrap up', 'ends up') is medium."""
READS = ()

CONCLUDE_STEMS = ("conclu", "summar", "overall", "summing", "总之", "总结", "结论", "综合",
                  "总而言之", "вывод", "заключ", "結論", "まとめ")
CONCLUDE_PIECES = {"clus", "clusion", "clusions", "ions", "ion"}
CLOSING_WORDS = {"therefore", "thus", "hence", "finally", "ultimately", "final", "altogether",
                 "foregoing", "essence", "</think>", "以上", "最后", "最终", "remember", "hope", "references", "discussion", "findings", "outlook", "closing", "together", "yes"}
PHRASAL_VERBS = {"wrap", "wrapped", "wrapping", "sum", "sums", "summed", "summing", "ends", "end",
                 "ending", "ended"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    is_conclude = any(stem in tok for stem in CONCLUDE_STEMS) or (
        tok in CONCLUDE_PIECES and prev in ("clus", "clusion"))
    if is_conclude:
        if prev == "in":
            value = -8.0
        elif prev in ("", ".", "!", "?"):
            value = -5.0
        else:
            value = -3.5
    elif tok in CLOSING_WORDS:
        value = -0.5
    elif tok == "up" and prev in PHRASAL_VERBS:
        value = -2.0
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Flag a small set of rhetorical transitions and text-boundary markers.

The strongest recurring signal is the end of an assistant reasoning block;
conclusion words such as “therefore”, “thus”, and “hence” are weaker cues.
"""
import unicodedata

READS = ()

CONCLUSIONS = {"therefore", "thus", "hence", "conclude"}


def last_word(text):
    word = []
    for char in reversed(text):
        if unicodedata.category(char).startswith("L"):
            word.append(char)
        elif word:
            break
    return "".join(reversed(word)).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    text = (tail + token)[-48:]
    lower = token.lower()

    if "</think>" in token:
        value = -1.1
    elif last_word(text) in CONCLUSIONS:
        value = -0.65
    else:
        value = 0.0

    return (doc, text), float(value)

programs.sol:
"""Approximate a negative spelling detector centered on 'ago' and 'go'.

Recognize short Latin go-fragments, Russian genitive -го endings, and
Korean -고, plus weaker related ko/ho and Japanese syllables. Leading
spaces and token length distinguish words from fragments. All predictions
use only the current token, with zero for unmatched spellings.
"""
READS = ()


def response(token):
    word = token.strip().lower()
    whole = token.startswith(' ')
    if word == 'ago':
        return -5.9 if whole else -4.9
    if word == 'go':
        return -1.25 if whole else -2.1
    if word in ('.go', '-go', '_go', '/go'):
        return -1.9
    if word.endswith('го'):
        if whole:
            if word == 'того':
                return -4.7
            if word == 'всего':
                return -3.2
            if word in ('его', 'него', 'чего'):
                return -1.3
            if word in ('много', 'немного', 'долго'):
                return -0.4
            return -2.1
        return -max(1.0, 3.5 - 0.18 * len(word))
    if word.endswith('go'):
        if word == 'tego':  # Polish genitive 'of that'.
            return -3.7
        if whole or len(word) > 5:
            return -0.6
        return -3.2 if word in ('igo', 'ango') else -1.9
    if word.endswith('고'):
        return -2.3 if len(word) <= 2 else -1.2
    if word in ('구', 'ご', 'ゴ'):
        return -1.3
    if word in ('ko', 'ico', 'ко', 'コ', 'goes', 'going'):
        return -0.6
    if word == 'ho':
        return -0.5 if whole else -1.6
    return 0.0


def step(carry, prefix, upstream):
    return None, float(response(prefix.token_strings[-1]))

"""A small lexical approximation of transaction and access vocabulary.

Listed words about enrolling, buying, paying, accounts, credentials and rewards
get negative activations; unlisted tokens get zero. Local phrases distinguish
strong responses ('exit code', 'sign up', 'pre-order') from weaker programming
or ordering senses. A few translated words and split-word endings are included.
This captures conspicuous negative responses, not the component's many small
background responses. The 48-character history resets at document boundaries.
"""

import re

READS = ()

# Strength groups within the transaction/access vocabulary.
LEXICON = (
    (-0.90, 'membership subscription deposit redeem'),
    (-0.58, 'cart checkout enrollment enroll enrol '
            'reservation reservations orders signup'),
    (-0.46, 'registration registering earned earn earning'),
    (-0.35, 'purchase purchases ticket tickets payment '
            'savings discount discounts receipt enrolled'),
    (-0.27, 'account accounts card password register payments '
            'save subscribe unsubscribe login'),
    (-0.30, 'code access trial demo refund basket store shipping'),
    (-0.50, 'deposits'),
    (-0.55, 'subscriptions'),
    (-0.22, 'ordering deposited'),
    (-0.20, 'fee fees gift casino donate voucher coupon'),
    (-0.13, 'members pass course courses receive cards registered'),
    (-0.06, 'free now need sign buy'),
    (-0.03, 'up member'),
    (-0.45, 'codes код кода коды codice código'),
    (-0.68, 'заказ заказа заказов регистра регистрации'),
    (-0.35, 'inscription anmeldung anmelden carrito pedido compra'),
)
WORDS = {word: value for value, words in LEXICON for word in words.split()}

# Chinese and Japanese code, membership, booking, payment and reward vocabulary.
TRANSLATIONS = (
    (-0.80, '码 積分 积分 名额 會員 会员'),
    (-0.55, '券 卡 订单 訂單 注册 註冊 报名 報名 ポイント 申し込み 预订 預訂'),
    (-0.38, '优惠 優惠 支付 付款 登录 登錄 退货 退貨 缴费 免費 無料 体验 定制 '
            '試 试 費 费 确认 確認 コース 课程'),
    (-0.23, '入 送 付 購 購買 订 訂'),
)
WORDS.update({word: value for value, words in TRANSLATIONS for word in words.split()})

CODE_CONTEXTS = {
    'exit': -1.50, 'qr': -1.65,
    'promotion': -1.0, 'promo': -1.0, 'redemption': -1.0, 'coupon': -1.0,
    'status': -0.90, 'error': -0.65, 'return': -0.65,
    'source': -0.12, 'original': -0.12, 'following': -0.12,
}
SPLIT_TRANSACTION_WORDS = {
    'depositing', 'redeeming', 'enrolment', 'enrollment',
    'registration', 'membership', 'subscription', 'purchase',
}
SORTING_WORDS = {'ascending', 'descending', 'increasing', 'decreasing', 'alphabetical'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == document else ''
    token = prefix.token_strings[-1].casefold()
    word = token.strip().strip('._/-')
    value = WORDS.get(word, 0.0)
    match = re.search(r'([a-z]+)\s*$', history)
    previous_word = match.group(1) if match else ''

    if token and token[0].isalpha() and word not in WORDS:
        ending = re.search(r'[a-z]+$', history + token)
        if ending and ending.group() in SPLIT_TRANSACTION_WORDS:
            value = -0.55

    if word in {'code', 'codes'}:
        value = CODE_CONTEXTS.get(previous_word, value)
    elif word == 'up' and previous_word in {'sign', 'signed', 'signing'}:
        value = -0.80 if previous_word == 'signed' else -1.35
    elif word == 'order':
        if previous_word == 'pre':
            value = -1.05
        elif re.search(r'\b(placing|place) (an|your)\s*$', history):
            value = -1.25
        elif previous_word == 'in':
            value = -0.18
        elif previous_word in SORTING_WORDS:
            value = 0.0
        elif previous_word == 'your':
            value = -1.10
        elif previous_word in {'an', 'to'}:
            value = -0.70
        else:
            value = -0.43
    elif word == 'account':
        if previous_word in {'capital', 'standard', 'service'}:
            value = -0.06
        elif previous_word == 'into':
            value = -0.14
        elif previous_word in {'your', 'an', 'free'}:
            value = -0.65
    elif word in {'card', 'cards'} and previous_word in {'credit', 'debit', 'payment'}:
        value = -0.68 if word == 'card' else -0.40
    elif word == 'cart' and previous_word == 'shopping':
        value = -0.98
    elif word == 'access' and previous_word in {'get', 'free', 'instant', 'unlimited'}:
        value = -0.65
    elif word in {'course', 'courses'} and previous_word in {'online', 'introductory'}:
        value = -0.50
    elif word == 'now' and previous_word in {'play', 'join', 'subscribe', 'order'}:
        value = -0.65
    elif word == 'for' and previous_word == 'signup':
        value = -0.75
    elif word == 'shipping' and previous_word == 'free':
        value = -0.80
    elif word == 'membership' and previous_word == 'free':
        value = -1.40

    return (document, (history + token)[-48:]), float(value)

"""Iberian plural morphology versus Latinate word stems.

Plural articles, quantifiers and short s-endings receive negative values,
stronger in Spanish/Portuguese context. Latinate stems receive positive
values. Language strength comes from a decaying count of complete
Iberian words, accents and endings. State resets between documents.
This approximates salient morphology, not every lexical or contextual effect.
"""
import re
import unicodedata
from functools import lru_cache

READS = ()

ARTICLES = set('aos dos las los unas unos'.split())

AMBIGUOUS = set('as das nas nos os'.split())

PLURAL_WORDS = set("""
algumas algunas algunos alguns ambos aquelas aqueles esas esos estas estes
estos mayores mejores melhores menos meus minhas mis muchas muchos muitas
muitos nuestras nuestros otras otros seguintes siguientes todas todos tus
varias varios vossos
""".split())

THIRD_POSSESSIVES = set('seus suas sus'.split())

NUMBERS = set('dois miles milhões millones seis tres três'.split())

SINGULAR = set("""
algo cuanto dia día essa esse esta este esto hay lo quanto tanto vez
""".split())

STEMS = set("""
administr alter aplic coment compart compr comunic conced conoc desarroll
educ efectu evalu func gener increment inform limit modific mov oper
orient particip permit prepar produc proporcion provoc public realiz recib
reconoc regul relacion remov represent satisf trabaj utiliz
""".split())

IBERIAN = set("""
agora ainda al além antes apenas assim años cada con cual cualquier cuando
cuanto cuál cómo del depois desde desta deste donde elas eles era es essa
esse esta estas este esto estos foi ha hacer han hasta hay hemos isso isto
las los mesmo muchos muita muito muy más necesario ni nos nuestra nuestras
nuestro nuestros num numa não nós onde otras otros ou para pela pelas pelo
pelos pero por porque puede pueden qual quien qué sendo será seu seus sido
sin sino sobre su sua suas sus são sé también também tem ter tiene tienen
toda todas todos tudo um uma umas una unas unos uns você às é
""".split())

WEAK = set("""
ao aos com da das de do dos e em en la mais mas nas nos o os que se un y
""".split())

ENDINGS = {
    'as': (-0.103, -1.143),
    'os': (-0.104, -0.91),
    'es': (0.046, -0.725),
    'is': (-0.075, -1.131),
    'ais': (-0.461, -1.553),
}

@lru_cache(maxsize=4096)
def evidence(word):
    ib = 1.0 if word in IBERIAN else 0.15 if word in WEAK else 0.0
    if any(c in 'áíóúñãõ' for c in word): ib = max(ib, 0.6)
    if word.endswith(('ción', 'ciones', 'ção', 'ções')): ib = max(ib, 1.0)
    return ib

@lru_cache(maxsize=8192)
def response(token):
    """Return (baseline activation, additional Iberian-context activation)."""
    w = token.strip().lower()
    space = token[:1].isspace()
    if not w.isalpha() or not all(
            'a' <= c <= 'z' or c in 'áéíóúüñãõâêôçàèìòù' for c in w):
        return (-0.002, -0.01)
    normal = ''.join(c for c in unicodedata.normalize('NFD', w)
                     if not unicodedata.combining(c))
    if space:
        if w in ARTICLES: return (-0.294, -1.106)
        if w in AMBIGUOUS: return (0.006, -1.182)
        if w in ('más', 'mas', 'mais'): return (-0.184, -0.922)
        if w in ('del', 'pelo', 'pela', 'pelos', 'pelas'): return (0.103, -0.921)
        if w in SINGULAR: return (0.037, -0.522)
        if w == 'la': return (0.104, -0.36)
        if w in ('por', 'tras', 'sin', 'hasta'): return (0.147, -0.417)
        if w in ('con', 'com', 'em'): return (-0.019, 0.319)
    if w in PLURAL_WORDS: return (-0.464, -0.481)
    if w in THIRD_POSSESSIVES: return (-0.074, -0.297)
    if w in NUMBERS: return (-0.297, -0.672)
    if not space and normal in ENDINGS: return ENDINGS[normal]
    if w == 's': return (0.007, -0.506)
    if w.endswith('s'):
        if space: return (-0.006, -0.191)
        if normal.endswith(('ados', 'adas', 'idos', 'idas', 'amos', 'emos', 'imos')):
            return (-0.216, -0.108)
        return ((-0.015, -0.547) if normal.endswith(('as', 'os', 'es', 'is'))
                else (-0.002, -0.193))
    if w in STEMS: return (0.012, 0.671)
    if len(w) == 1: return (-0.002, 0.065)
    return (0.0, 0.023) if w[-1] in 'aeiouáéíóúãõâêô' else (-0.002, 0.136)

@lru_cache(maxsize=4096)
def pieces(token):
    return re.findall(r'[^\W\d_]+|[\W\d_]+', token.lower())

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    ib, word = (0.0, '') if carry is None or carry[0] != doc else carry[1:]
    ib *= 0.93
    token = prefix.token_strings[-1]
    for piece in pieces(token):
        if piece[0].isalpha(): word = (word + piece)[-40:]
        elif word:
            ib += evidence(word)
            word = ''
    # The unfinished current word supplies only a tentative half-strength cue.
    tentative = evidence(word) if word else 0.0
    language = min(1.0, (ib + 0.5*tentative) / 2.0)
    if token.strip() and token.strip()[0].isupper(): language *= 0.7
    base, context = response(token)
    return (doc, ib, word), float(base + context*language)

programs.luna:
"""Uses a near-zero baseline with weak lexical hints. The larger nudge is
for common Spanish/Portuguese article-like forms; the smaller one is for a
few other short forms. Most context-specific activations are left unmodeled.
"""
READS = ()

STRONG_ARTICLES = {"los", "las", "os", "as", "dos", "del", "les"}
OTHER_WORDS = {"als", "mis", "tres", "es", "is"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    value = -0.00225
    if word in STRONG_ARTICLES:
        value -= 0.085
    elif word in OTHER_WORDS:
        value -= 0.0425
    return None, value

"""Estimate comment and Markdown-marker activations from visible punctuation."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    mark = token.lstrip()
    value = -0.0036

    if mark.startswith("###"):
        value -= 1.9
    elif mark.startswith("#"):
        value -= 0.8
    elif mark.startswith("///"):
        value -= 0.9
    elif mark.startswith("//"):
        value -= 0.58
    elif "**" in token:
        value -= 1.15
    elif "*" in token:
        value -= 0.4
    elif "```" in token:
        value += 0.3
    elif "`" in token:
        value -= 0.44
    return carry, float(-0.0036 + 0.85 * (value + 0.0036))

programs.sol:
"""Mostly a lexical 'stack' detector, not a test for programming context.

It fires on 'stack' in prose or identifiers, less on its inflections and
compounds, and weakly on heaps, queues, linked structures, piles and towers.
Similar spellings ('static', 'staff', 'stick', and '-ack' fragments) also
respond.  Case and attached punctuation modify the strength.  A one-token
memory handles split words and phrases such as 'stack of' and 'linked list'.
Everything else is zero; memory resets at document boundaries.
"""

READS = ()
BOUNDARIES = ' \t\r\n._-/()[]{}\\:;\"\''


def word_response(token, word):
    lower = word.lower()
    if lower == 'stack':
        value = 7.7 if word == 'Stack' else 7.0
        if word.isupper():
            value = 6.0
        if token.startswith('('):
            value = 6.3 if word == 'Stack' else 5.8
        elif token.startswith('_'):
            value = 8.0 if word.isupper() else 6.7
        elif token.startswith('\t'):
            value = 6.2
        elif token.startswith(' ') and word == 'Stack':
            value = 7.9
        elif token.startswith('.'):
            value = 7.5
        return value
    if lower == 'stacks':
        return 5.8
    if lower in ('stacked', 'stacking'):
        return 3.9 if lower == 'stacked' else 3.4
    if 'stack' in lower:
        if 'print' in lower:
            return 0.27
        if lower == 'haystack':
            return 0.8
        if lower == 'stacksize':
            return 4.4
        return 2.5 if lower.startswith('stack') else 1.8

    # Chinese words for stack, heap, layering; Japanese for staff.
    if word in ('栈', '棧'):
        return 6.2
    if word == '堆':
        return 3.3
    if word in ('叠', '疊'):
        return 2.0
    if word == 'スタッフ':
        return 0.8
    if word == '塔':
        return 0.6

    if lower in ('heap', 'heaps'):
        return 1.8 if word[:1].isupper() else 1.4
    if lower in ('queue', 'queues'):
        return 1.5 if word[:1].isupper() else 0.9
    if lower in ('deque', 'priorityqueue'):
        return 1.6
    if lower in ('linked', 'linkedlist', 'linkedhashmap'):
        return 1.4 if word[:1].isupper() else 0.75
    if lower in ('static', 'statically'):
        return 0.94
    if lower == 'staff':
        return 1.14
    if lower in ('stick', 'sticks'):
        return 0.4
    if lower in ('pile', 'piles', 'tower', 'towers'):
        return 0.65

    # Word fragments with the spelling ending '-ack'.
    if token == 'ack':
        return 0.35
    if token in ('acks', 'acker', 'ackers'):
        return 0.8
    if token in ('acked', 'acking'):
        return 0.5
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip(BOUNDARIES)
    lower = word.lower()
    value = word_response(token, word)

    if previous == 'stack':
        if token == 's':
            value = 3.6
        elif token == 'ed':
            value = 2.5
        elif token == 'er':
            value = 0.85
        elif lower == 'of':
            value = 2.7
        elif lower == 'trace':
            value = 0.8
        elif lower == 'size':
            value = 0.65
        elif lower == 'overflow':
            value = 1.4
    elif lower == 'of':
        if previous == 'stacks':
            value = 1.7
        elif previous in ('heap', 'heaps'):
            value = 0.7
        elif previous == 'staff':
            value = 0.35
    elif previous == 'linked' and lower in ('list', 'lists'):
        value = 1.25
    elif previous == 'st':
        if token == 'acks':
            value = 3.7
        elif token == 'aff':
            value = 1.1
        elif token == 'icks':
            value = 0.95

    return (doc, lower), float(value)
